INSERT INTO `services` (`id`, `locale`, `slug`, `title`, `icon`, `color`, `image`, `shortDesc`, `fullDesc`, `features`, `faq`, `sortOrder`, `legacyId`, `isDefault`, `status`, `createdAt`, `updatedAt`)
VALUES
  (1, 'fr', 'vente-equipements', 'Vente d''Équipements', 'shopping-cart', 'sari-blue', 'https://images.unsplash.com/photo-1516574187841-cb9cc2ca948b?w=1920', 'Large gamme d''équipements médicaux neufs et reconditionnés', 'Nous proposons une sélection rigoureuse d''équipements médicaux provenant des plus grands fabricants mondiaux. Que ce soit pour l''imagerie, le bloc opératoire ou la réanimation, nous vous accompagnons dans le choix du matériel le plus adapté à votre pratique et à votre budget.', '["Audit de vos besoins","Comparatif des marques","Négociation des tarifs","Garantie constructeur étendue"]', '[{"q":"Proposez-vous du matériel reconditionné ?","a":"Oui, nous proposons une gamme certifiée de matériel reconditionné avec une garantie de 12 mois."},{"q":"Quels sont les délais de livraison ?","a":"Les délais varient de 24h pour les consommables à 4-6 semaines pour les équipements lourds sur commande."},{"q":"Vos équipements sont-ils homologués pour le marché algérien ?","a":"Oui. Chaque appareil est livré avec sa certification CE et son marquage ISO 13485, et nous fournissons le dossier technique exigé par l''Agence nationale des produits pharmaceutiques pour l''enregistrement des dispositifs médicaux."},{"q":"Gérez-vous les formalités douanières et le transit ?","a":"Nous prenons en charge l''importation de bout en bout : domiciliation bancaire, dédouanement au port d''Alger ou d''Oran, et acheminement jusqu''à votre établissement. Vous ne traitez qu''un seul interlocuteur."},{"q":"Quelles facilités de paiement proposez-vous ?","a":"Nous acceptons le virement bancaire, la lettre de crédit documentaire et, pour les structures publiques, le paiement sur bon de commande administratif. Un échelonnement est possible sur les équipements lourds."}]', 1, 'svc-1', 1, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (2, 'fr', 'installation-formation', 'Installation & Formation', 'users', 'green-500', 'https://images.unsplash.com/photo-1581056771107-24ca5f033842?w=1920', 'Installation sur site et formation du personnel', 'L''achat d''un équipement ne s''arrête pas à la livraison. Nos ingénieurs biomédicaux assurent une installation clé en main, le calibrage des appareils et une formation complète de vos équipes pour une prise en main immédiate et sécurisée.', '["Installation clé en main","Calibrage et tests de sécurité","Formation théorique et pratique","Support documentaire complet"]', '[{"q":"La formation est-elle incluse dans le prix ?","a":"Oui, une session de formation de base est incluse pour tout achat d''équipement lourd."},{"q":"Pouvons-nous former de nouveaux arrivants plus tard ?","a":"Absolument, nous proposons des sessions de formation additionnelles sur devis."},{"q":"La formation est-elle dispensée en arabe ?","a":"Nos formateurs interviennent en arabe, en français ou en anglais selon la préférence de votre équipe. Les supports écrits sont remis dans les trois langues."},{"q":"Combien de temps dure la mise en service d''un plateau technique ?","a":"Comptez une à deux journées pour un appareil isolé, et de trois à cinq jours pour un plateau complet incluant le raccordement, l''étalonnage et la validation des mesures."},{"q":"Délivrez-vous une attestation aux participants ?","a":"Chaque participant reçoit une attestation nominative précisant les modules suivis, document utile lors des inspections et des démarches d''accréditation."}]', 2, 'svc-2', 1, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (3, 'fr', 'maintenance-sav', 'Maintenance & SAV', 'wrench', 'orange-500', 'https://images.unsplash.com/photo-1581092160607-ee22621dd758?w=1920', 'Contrats de maintenance et service après-vente', 'La disponibilité de vos équipements est critique. Nous offrons des contrats de maintenance préventive et curative, avec des interventions garanties sous 24h/48h et un stock de pièces détachées important.', '["Maintenance préventive programmée","Intervention d''urgence 24/7","Pièces détachées d''origine","Rapports d''intervention détaillés"]', '[{"q":"Quels sont les types de contrats de maintenance ?","a":"Nous proposons des contrats ''Sérénité'' (tout inclus) et ''Essentiel'' (main d''œuvre incluse, pièces en sus)."},{"q":"Intervenez-vous sur toutes les marques ?","a":"Nous sommes agréés sur les principales marques et pouvons intervenir sur la plupart des équipements du marché."},{"q":"Quel est votre délai d''intervention en cas de panne ?","a":"Sous contrat premium, un technicien intervient sous 24 heures à Alger et sous 48 heures dans le reste du pays. Un diagnostic à distance est lancé dès l''appel afin d''apporter la bonne pièce."},{"q":"Disposez-vous des pièces détachées en stock ?","a":"Notre magasin d’Alger conserve les pièces d’usure des gammes que nous distribuons. Les pièces spécifiques sont commandées auprès du fabricant sous sept à dix jours ouvrés."},{"q":"Fournissez-vous un équipement de remplacement pendant l''immobilisation ?","a":"Les contrats premium incluent le prêt d''un appareil équivalent dès lors que la réparation dépasse 72 heures, afin que votre activité ne s''interrompe pas."}]', 3, 'svc-3', 1, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (4, 'fr', 'fourniture-de-consommables', 'Fourniture de Consommables', 'package', 'purple-500', 'https://images.unsplash.com/photo-1583912268183-a34d41fe464a?w=1920', 'Fourniture régulière de consommables pour hôpitaux et cliniques', 'Ne soyez plus jamais en rupture de stock. Nous mettons en place des approvisionnements automatiques et des tarifs dégressifs pour vos consommables quotidiens (gants, masques, désinfectants, matériel de soin).', '["Catalogue de plus de 5000 références","Livraison en 24/48h","Tarifs dégressifs selon volume","Gestion des stocks à façon"]', '[{"q":"Y a-t-il un minimum de commande ?","a":"La livraison est gratuite dès 500€ HT d''achat."},{"q":"Pouvons-nous avoir des échantillons ?","a":"Oui, nous fournissons des échantillons pour tester la qualité avant un engagement."},{"q":"Assurez-vous un réapprovisionnement automatique ?","a":"Nous établissons un calendrier de livraison fondé sur votre consommation réelle, avec alerte avant rupture. Vous gardez la main pour ajuster les quantités à tout moment."},{"q":"Comment garantissez-vous la chaîne du froid ?","a":"Les produits thermosensibles voyagent en conteneurs réfrigérés avec enregistreur de température ; le relevé est joint au bon de livraison et archivé pendant trois ans."},{"q":"Livrez-vous dans les wilayas du Sud ?","a":"Oui, nous desservons l''ensemble du territoire, y compris Tamanrasset, Adrar et Illizi. Les délais y sont majorés de deux à quatre jours selon la liaison routière."}]', 4, 'svc-4', 1, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (1001, 'en', 'equipment-sales', 'Equipment Sales', 'shopping-cart', 'sari-blue', 'https://images.unsplash.com/photo-1516574187841-cb9cc2ca948b?w=1920', 'Wide range of new and refurbished medical equipment', 'We offer a rigorous selection of medical equipment from the world''s leading manufacturers. Whether for imaging, the operating room, or intensive care, we assist you in choosing the equipment best suited to your practice and budget.', '["Needs assessment","Brand comparison","Price negotiation","Extended manufacturer warranty"]', '[{"q":"Do you offer refurbished equipment?","a":"Yes, we offer a certified range of refurbished equipment with a 12-month warranty."},{"q":"What are the delivery lead times?","a":"Lead times vary from 24 hours for consumables to 4-6 weeks for heavy equipment made to order."},{"q":"Is your equipment approved for the Algerian market?","a":"Yes. Every device ships with CE certification and ISO 13485 marking, and we provide the technical file required by the national pharmaceutical products agency to register medical devices."},{"q":"Do you handle customs clearance and freight?","a":"We manage the full import chain: bank domiciliation, clearance at the port of Algiers or Oran, and delivery to your facility. You deal with a single point of contact."},{"q":"What payment terms do you offer?","a":"We accept bank transfer, documentary letter of credit and, for public institutions, payment against an administrative purchase order. Instalments are available on heavy equipment."}]', 1, 'svc-1', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (1002, 'en', 'installation-training', 'Installation & Training', 'users', 'green-500', 'https://images.unsplash.com/photo-1581056771107-24ca5f033842?w=1920', 'On-site installation and staff training', 'Purchasing equipment doesn''t stop at delivery. Our biomedical engineers ensure turn-key installation, device calibration, and complete training for your teams for an immediate and secure startup.', '["Turn-key installation","Calibration and safety testing","Theoretical and practical training","Comprehensive documentary support"]', '[{"q":"Is training included in the price?","a":"Yes, a basic training session is included with any purchase of heavy equipment."},{"q":"Can we train new employees later on?","a":"Abolutely, we offer additional training sessions upon quote."},{"q":"Is the training delivered in Arabic?","a":"Our trainers work in Arabic, French or English depending on your team’s preference. Written material is handed over in all three languages."},{"q":"How long does commissioning a technical unit take?","a":"Allow one to two days for a single device, and three to five days for a complete unit including connection, calibration and measurement validation."},{"q":"Do participants receive a certificate?","a":"Each participant receives a personal certificate listing the modules completed — a useful document during inspections and accreditation procedures."}]', 2, 'svc-2', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (1003, 'en', 'maintenance-after-sales-service', 'Maintenance & After-Sales Service', 'wrench', 'orange-500', 'https://images.unsplash.com/photo-1581092160607-ee22621dd758?w=1920', 'Maintenance contracts and after-sales service', 'The availability of your equipment is critical. We offer preventive and corrective maintenance contracts, with guaranteed intervention within 24h/48h and a substantial stock of spare parts.', '["Scheduled preventive maintenance","24/7 emergency response","Original spare parts","Detailed service reports"]', '[{"q":"What types of maintenance contracts do you offer?","a":"We offer ''Serenity'' (all-inclusive) and ''Essential'' (labor included, parts extra) contracts."},{"q":"Do you service all brands?","a":"We are authorized for major brands and can service most equipment on the market."},{"q":"How fast do you respond to a breakdown?","a":"Under a premium contract a technician arrives within 24 hours in Algiers and 48 hours elsewhere in the country. Remote diagnosis starts as soon as you call so the right part is brought along."},{"q":"Do you keep spare parts in stock?","a":"Our Algiers warehouse holds wear parts for the ranges we distribute. Device-specific parts are ordered from the manufacturer within seven to ten working days."},{"q":"Do you provide replacement equipment during downtime?","a":"Premium contracts include the loan of an equivalent device whenever a repair exceeds 72 hours, so your activity is never interrupted."}]', 3, 'svc-3', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (1004, 'en', 'supply-of-consumables', 'Supply of Consumables', 'package', 'purple-500', 'https://images.unsplash.com/photo-1583912268183-a34d41fe464a?w=1920', 'Regular supply of consumables for hospitals and clinics', 'Never run out of stock again. We set up automatic restocking and volume discounts for your daily medical consumables (gloves, masks, disinfectants, care supplies).', '["Catalog of over 5,000 items","24/48h delivery","Volume discounts","Custom stock management"]', '[{"q":"Is there a minimum order?","a":"Delivery is free for purchases over €500 excl. tax."},{"q":"Can we get samples?","a":"Yes, we provide samples to test quality before committing."},{"q":"Do you offer automatic replenishment?","a":"We set a delivery schedule based on your actual consumption, with an alert before you run out. You can adjust quantities at any time."},{"q":"How is the cold chain guaranteed?","a":"Temperature-sensitive products travel in refrigerated containers fitted with a data logger; the record is attached to the delivery note and archived for three years."},{"q":"Do you deliver to the southern wilayas?","a":"Yes, we cover the whole country including Tamanrasset, Adrar and Illizi. Lead times there are two to four days longer depending on the road link."}]', 4, 'svc-4', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (2001, 'ar', 'بيع-المعدات', 'بيع المعدات', 'shopping-cart', 'sari-blue', 'https://images.unsplash.com/photo-1516574187841-cb9cc2ca948b?w=1920', 'تشكيلة واسعة من المعدات الطبية الجديدة والمجددة', 'نقدم اختيارًا دقيقًا للمعدات الطبية من أكبر المصنعين العالميين. سواء كان للتصوير الطبي، غرف العمليات أو الإننعاش، نرافقكم في اختيار المعدات الأكثر ملاءمة لممارستكم ولميزانيتكم.', '["تدقيق احتياجاتكم","مقارنة بين العلامات التجارية","التفاوض على الأسعار","ضمان ممتد من المصنع"]', '[{"q":"هل تقدمون معدات مجددة؟","a":"نعم، نقدم مجموعة معتمدة من المعدات المجددة مع ضمان لمدة 12 شهرًا."},{"q":"ما هي آجال التسليم؟","a":"تتراوح الآجال من 24 ساعة للمستلزمات إلى 4-6 أسابيع للمعدات الثقيلة عند الطلب."},{"q":"هل معداتكم معتمدة في السوق الجزائرية؟","a":"نعم. يُسلَّم كل جهاز بشهادة CE وعلامة ISO 13485، ونوفر الملف التقني الذي تطلبه الوكالة الوطنية للمواد الصيدلانية لتسجيل الأجهزة الطبية."},{"q":"هل تتكفلون بالإجراءات الجمركية والنقل؟","a":"نتولى سلسلة الاستيراد كاملة: التوطين البنكي، والتخليص الجمركي في ميناء الجزائر أو وهران، والتوصيل إلى مؤسستكم. تتعاملون مع جهة واحدة فقط."},{"q":"ما هي تسهيلات الدفع المتاحة؟","a":"نقبل التحويل البنكي والاعتماد المستندي، وبالنسبة للمؤسسات العمومية الدفع مقابل سند طلب إداري. كما يمكن تقسيط ثمن المعدات الثقيلة."}]', 1, 'svc-1', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (2002, 'ar', 'التركيب-والتدريب', 'التركيب والتدريب', 'users', 'green-500', 'https://images.unsplash.com/photo-1581056771107-24ca5f033842?w=1920', 'التركيب في الموقع وتدريب الموظفين', 'شراء المعدات لا ينتهي عند التسليم. يضمن مهندسونا البيوطبيون تركيبًا جاهزًا للاستخدام، معايرة الأجهزة وتدريبًا كاملاً لفرقكم للاستخدام الفوري وآلآمن.', '["تركيب جاهز للاستخدام","المعايرة واختبارات السلامة","تدريب نظري وتطبيقي","دعم توثيقي كامل"]', '[{"q":"هل التدريب مشمول في السعر؟","a":"نعم، تتضمن كل عملية شراء لمعدات ثقيلة دورة تدريبية أساسية."},{"q":"هل يمكننا تدريب موظفين جدد لاحقًا؟","a":"بالتأكيد، نقدم دورات تدريبية إضافية بناءً على طلب سعر."},{"q":"هل يقدَّم التدريب باللغة العربية؟","a":"يعمل مدربونا بالعربية أو الفرنسية أو الإنجليزية حسب تفضيل فريقكم، وتُسلَّم المستندات المكتوبة باللغات الثلاث."},{"q":"كم تستغرق عملية تشغيل منصة تقنية؟","a":"يستغرق الأمر يومًا إلى يومين لجهاز واحد، ومن ثلاثة إلى خمسة أيام لمنصة كاملة تشمل التوصيل والمعايرة والتحقق من القياسات."},{"q":"هل تمنحون شهادة للمشاركين؟","a":"يتلقى كل مشارك شهادة اسمية تحدد الوحدات التي أتمها، وهي وثيقة مفيدة عند عمليات التفتيش وإجراءات الاعتماد."}]', 2, 'svc-2', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (2003, 'ar', 'الصيانة-وخدمة-ما-بعد-البيع', 'الصيانة وخدمة ما بعد البيع', 'wrench', 'orange-500', 'https://images.unsplash.com/photo-1581092160607-ee22621dd758?w=1920', 'عقود الصيانة وخدمة ما بعد البيع', 'توفر معداتكم أمر حاسم. نقدم عقود صيانة وقائية وعلاجية، مع تدخلات مضمونة في غضون 24 إلى 48 ساعة ومخزون كبير من قطع الغيار.', '["صيانة وقائية مبرمجة","تدخل طارئ على مدار 24/7","قطع غيار أصلية","تقارير تدخل تفصيلية"]', '[{"q":"ما هي أنواع عقود الصيانة المتاحة؟","a":"نقدم عقود ''الطمأنينة'' (شاملة لكافة الخدمات) وعقود ''الأساسية'' (تشمل اليد العاملة، وقطع الغيار إضافية)."},{"q":"هل تتدخلون لجميع العلامات التجارية؟","a":"نحن معتمدون لدى العلامات التجارية الرئيسية ويمكننا التدخل في معظم المعدات الموجودة في السوق."},{"q":"ما هي مدة التدخل في حالة العطل؟","a":"بموجب العقد المميز يصل التقني خلال 24 ساعة في الجزائر العاصمة وخلال 48 ساعة في باقي الولايات، ويبدأ التشخيص عن بُعد فور اتصالكم لإحضار القطعة المناسبة."},{"q":"هل تتوفر لديكم قطع الغيار في المخزون؟","a":"يحتفظ مستودعنا بالجزائر العاصمة بقطع الاستهلاك للتشكيلات التي نوزعها، أما القطع الخاصة فتُطلب من المصنّع خلال سبعة إلى عشرة أيام عمل."},{"q":"هل توفرون جهازًا بديلًا أثناء فترة التوقف؟","a":"تتضمن العقود المميزة إعارة جهاز مماثل متى تجاوز الإصلاح 72 ساعة، حتى لا يتوقف نشاطكم."}]', 3, 'svc-3', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (2004, 'ar', 'توفير-المستلزمات-الطبية', 'توفير المستلزمات الطبية', 'package', 'purple-500', 'https://images.unsplash.com/photo-1583912268183-a34d41fe464a?w=1920', 'تزويد منتظم للمستشفيات والعيادات بالمستلزمات الطبية', 'لا تعانوا من نفاد المخزون بعد اليوم. نضع تحت تصرفكم نظام تزويد أوتوماتيكي وأسعارًا تنازلية لمستلزماتكم اليومية (قفازات، أقنعة، مطهرات، مستلزمات العناية).', '["كتالوج يضم أكثر من 5000 منتج","توصيل خلال 24/48 ساعة","أسعار تنازلية حسب الكمية","إدارة المخزون حسب الطلب"]', '[{"q":"هل هناك حد أدنى للطلب؟","a":"التوصيل مجاني ابتداءً من شراء بقيمة 500 يورو قبل احتساب الرسوم."},{"q":"هل يمكننا الحصول على عينات؟","a":"نعم، نوفر عينات لاختبار الجودة قبل الالتزام بالطلب."},{"q":"هل توفرون إعادة تموين تلقائية؟","a":"نضع جدول تسليم يستند إلى استهلاككم الفعلي مع تنبيه قبل نفاد المخزون، ويبقى بإمكانكم تعديل الكميات في أي وقت."},{"q":"كيف تضمنون سلسلة التبريد؟","a":"تُنقل المنتجات الحساسة للحرارة في حاويات مبردة مزودة بمسجل حرارة، ويُرفق التقرير بوصل التسليم ويُحفظ لمدة ثلاث سنوات."},{"q":"هل تسلّمون إلى ولايات الجنوب؟","a":"نعم، نغطي كامل التراب الوطني بما في ذلك تمنراست وأدرار وإليزي، مع آجال إضافية من يومين إلى أربعة أيام حسب الرابط الطرقي."}]', 4, 'svc-4', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3))
INSERT INTO `solutions` (`id`, `locale`, `slug`, `title`, `shortDesc`, `fullDesc`, `icon`, `image`, `color`, `productIds`, `features`, `faq`, `sortOrder`, `legacyId`, `isDefault`, `status`, `createdAt`, `updatedAt`)
VALUES
  (1, 'fr', 'diagnostic-imagerie', 'Diagnostic & Imagerie', 'Échographes, tensiomètres, stéthoscopes et équipements de diagnostic de haute précision.', '<p>Notre gamme de solutions de diagnostic et d''imagerie est conçue pour offrir une précision inégalée aux professionnels de santé. Nous proposons des équipements certifiés CE et conformes aux normes ISO 13485.</p><p>Que vous soyez un cabinet privé ou un grand hôpital, nous avons la solution adaptée à vos besoins spécifiques.</p>', 'stethoscope', 'https://images.unsplash.com/photo-1579154204601-01588f351e67?w=1920', 'sari-blue', '[1,4,5]', '["Imagerie haute résolution 4D","Connectivité WiFi et Bluetooth","Autonomie longue durée","Certification CE et ISO 13485","Écrans tactiles HD","Livraison et installation incluses"]', '[{"q":"Quels types d''échographes proposez-vous ?","a":"Nous proposons des échographes portables et fixes, avec différentes configurations de sondes (convexe, linéaire, endocavitaire). Tous nos appareils sont certifiés CE et conformes ISO 13485."},{"q":"Les tensiomètres sont-ils certifiés médicaux ?","a":"Oui, tous nos tensiomètres sont des dispositifs médicaux de classe IIa, certifiés CE avec validation clinique selon le protocole ESH."},{"q":"Proposez-vous la formation à l''utilisation ?","a":"Oui, une session de formation de base est incluse avec chaque achat. Des formations avancées sont disponibles en option."},{"q":"Proposez-vous une démonstration avant l’achat ?","a":"Nous organisons une démonstration dans votre service, avec vos propres cas d''usage, ou une visite de site chez un confrère déjà équipé. C''est la meilleure façon de valider l''ergonomie avec les utilisateurs finaux."},{"q":"Quelle garantie couvre ces équipements ?","a":"La garantie constructeur est de 24 mois pièces et main-d''œuvre, extensible à 60 mois. Elle couvre les défauts de fabrication et inclut les mises à jour logicielles de sécurité."},{"q":"Ces dispositifs s’intègrent-ils à notre système d’information ?","a":"Les appareils communicants sont compatibles DICOM et HL7, ce qui permet leur raccordement à un PACS ou à un dossier patient informatisé existant. Notre équipe technique valide l''interopérabilité avant la mise en production."}]', 0, 'sol-diagnostic', 1, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (2, 'fr', 'cardiologie', 'Cardiologie', 'ECG, défibrillateurs, moniteurs cardiaques et holters pour une surveillance optimale.', '<p>La cardiologie exige une fiabilité absolue. Nos équipements de surveillance cardiaque et de défibrillation sont conçus pour les situations d''urgence comme pour le suivi quotidien.</p>', 'heart-pulse', 'https://images.unsplash.com/photo-1559757175-5700dde675bc?w=1920', 'red-500', '[7]', '["ECG 3/5/12 dérivations","Défibrillateurs DSA et DAE","Moniteurs cardiaques temps réel","Holters ECG 24/48/72h","Conformité CE médical","Support technique 24/7"]', '[{"q":"Vos ECG sont-ils 12 dérivations ?","a":"Oui, nous proposons des ECG 3, 6 et 12 dérivations selon vos besoins. Tous nos ECG disposent d''un écran tactile et d''une imprimante thermique intégrée."},{"q":"Les défibrillateurs sont-ils faciles à utiliser ?","a":"Oui, tous nos DSA sont conçus pour une utilisation simple avec guide vocal pas à pas et analyse automatique du rythme en moins de 10 secondes."},{"q":"Proposez-vous une démonstration avant l’achat ?","a":"Nous organisons une démonstration dans votre service, avec vos propres cas d''usage, ou une visite de site chez un confrère déjà équipé. C''est la meilleure façon de valider l''ergonomie avec les utilisateurs finaux."},{"q":"Quelle garantie couvre ces équipements ?","a":"La garantie constructeur est de 24 mois pièces et main-d''œuvre, extensible à 60 mois. Elle couvre les défauts de fabrication et inclut les mises à jour logicielles de sécurité."},{"q":"Ces dispositifs s’intègrent-ils à notre système d’information ?","a":"Les appareils communicants sont compatibles DICOM et HL7, ce qui permet leur raccordement à un PACS ou à un dossier patient informatisé existant. Notre équipe technique valide l''interopérabilité avant la mise en production."}]', 0, 'sol-cardiology', 1, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (3, 'fr', 'imagerie-medicale', 'Imagerie Médicale', 'Scanners CT, IRM, radiologie numérique et solutions PACS/RIS.', '<p>Nos solutions d''imagerie médicale couvrent l''ensemble des besoins diagnostiques des établissements de santé. Du scanner CT 16 coupes à l''IRM 3T, nous proposons des équipements de dernière génération.</p>', 'scan', 'https://images.unsplash.com/photo-1516549655169-df83a0774514?w=1920', 'purple-500', '[]', '["Scanners CT 16 à 128 coupes","IRM 1.5T et 3T","Radiologie numérique DR/CR","Solutions PACS/RIS","Conformité HDS","Maintenance préventive"]', '[{"q":"Proposez-vous des scanners CT ?","a":"Oui, nous proposons une gamme complète de scanners CT, de 16 à 128 coupes, avec installation et formation incluses."},{"q":"Les IRM sont-ils compatibles avec tous les patients ?","a":"Oui, nos IRM sont adaptés à tous les profils de patients, y compris les enfants et les personnes claustrophobes."},{"q":"Proposez-vous une démonstration avant l’achat ?","a":"Nous organisons une démonstration dans votre service, avec vos propres cas d''usage, ou une visite de site chez un confrère déjà équipé. C''est la meilleure façon de valider l''ergonomie avec les utilisateurs finaux."},{"q":"Quelle garantie couvre ces équipements ?","a":"La garantie constructeur est de 24 mois pièces et main-d''œuvre, extensible à 60 mois. Elle couvre les défauts de fabrication et inclut les mises à jour logicielles de sécurité."},{"q":"Ces dispositifs s’intègrent-ils à notre système d’information ?","a":"Les appareils communicants sont compatibles DICOM et HL7, ce qui permet leur raccordement à un PACS ou à un dossier patient informatisé existant. Notre équipe technique valide l''interopérabilité avant la mise en production."}]', 0, 'sol-imagerie', 1, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (4, 'fr', 'chirurgie', 'Chirurgie', 'Instruments chirurgicaux, autoclaves, lampes scialytiques et tables opératoires.', '<p>Notre département chirurgie propose tous les équipements nécessaires aux blocs opératoires modernes, de la stérilisation à l''éclairage, en passant par les instruments de précision.</p>', 'syringe', 'https://images.unsplash.com/photo-1551076805-e1869033e561?w=1920', 'green-500', '[3,9]', '["Instruments chirurgicaux inox","Autoclaves classe B","Lampes scialytiques LED","Tables opératoires électriques","Stérilisation certifiée","Maintenance et SAV"]', '[{"q":"Vos autoclaves sont-ils classe B ?","a":"Oui, tous nos autoclaves sont classe B, conformes aux normes européennes EN 13060, avec cycle de séchage sous vide et traçabilité complète."},{"q":"Les lampes scialytiques sont-elles LED ?","a":"Oui, toutes nos lampes scialytiques sont LED avec une durée de vie de 50 000 heures, un IRC > 95 et une intensité jusqu''à 150 000 Lux."},{"q":"Proposez-vous une démonstration avant l’achat ?","a":"Nous organisons une démonstration dans votre service, avec vos propres cas d''usage, ou une visite de site chez un confrère déjà équipé. C''est la meilleure façon de valider l''ergonomie avec les utilisateurs finaux."},{"q":"Quelle garantie couvre ces équipements ?","a":"La garantie constructeur est de 24 mois pièces et main-d''œuvre, extensible à 60 mois. Elle couvre les défauts de fabrication et inclut les mises à jour logicielles de sécurité."},{"q":"Ces dispositifs s’intègrent-ils à notre système d’information ?","a":"Les appareils communicants sont compatibles DICOM et HL7, ce qui permet leur raccordement à un PACS ou à un dossier patient informatisé existant. Notre équipe technique valide l''interopérabilité avant la mise en production."}]', 0, 'sol-surgery', 1, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (5, 'fr', 'pediatrie', 'Pédiatrie', 'Couveuses néonatales, balances pédiatriques, photothérapie et matériel adapté.', '<p>Notre gamme pédiatrique est spécialement conçue pour les soins des nouveau-nés et des enfants, avec des équipements adaptés, sécurisés et doux.</p>', 'baby', 'https://images.unsplash.com/photo-1583947215259-38e31be8751f?w=1920', 'pink-500', '[12]', '["Couveuses néonatales","Balances pédiatriques 5g","Lampes de photothérapie","Thermomètres infrarouges","Moniteurs néonatals","Matériel adapté enfants"]', '[{"q":"Les couveuses sont-elles adaptées aux prématurés ?","a":"Oui, nos couveuses sont adaptées aux prématurés dès 28 semaines de gestation, avec contrôle précis de la température, humidité et oxygène."},{"q":"Les balances sont-elles précises ?","a":"Oui, nos balances pédiatriques ont une précision de 5g avec fonction maintien (Hold) pour les bébés agités et fonction tare pour les couches."},{"q":"Proposez-vous une démonstration avant l’achat ?","a":"Nous organisons une démonstration dans votre service, avec vos propres cas d''usage, ou une visite de site chez un confrère déjà équipé. C''est la meilleure façon de valider l''ergonomie avec les utilisateurs finaux."},{"q":"Quelle garantie couvre ces équipements ?","a":"La garantie constructeur est de 24 mois pièces et main-d''œuvre, extensible à 60 mois. Elle couvre les défauts de fabrication et inclut les mises à jour logicielles de sécurité."},{"q":"Ces dispositifs s’intègrent-ils à notre système d’information ?","a":"Les appareils communicants sont compatibles DICOM et HL7, ce qui permet leur raccordement à un PACS ou à un dossier patient informatisé existant. Notre équipe technique valide l''interopérabilité avant la mise en production."}]', 0, 'sol-pediatrics', 1, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (6, 'fr', 'urgence-reanimation', 'Urgence & Réanimation', 'Défibrillateurs, chariots d''urgence, moniteurs multiparamètres et aspirateurs.', '<p>Le service des urgences nécessite des équipements fiables et disponibles 24h/24. Nos solutions sont conçues pour la rapidité, la robustesse et l''efficacité en situation critique.</p>', 'activity', 'https://images.unsplash.com/photo-1516549655169-df83a0774514?w=1920', 'orange-500', '[7,15]', '["Défibrillateurs DSA/DAE","Chariots d''urgence complets","Moniteurs multiparamètres","Aspirateurs de sécrétions","Pousse-seringues","Support 24/7 garanti"]', '[{"q":"Les défibrillateurs sont-ils automatiques ?","a":"Oui, nous proposons des DSA (semi-automatiques) et DAE (entièrement automatiques) avec guide vocal et analyse du rythme en moins de 10 secondes."},{"q":"Les chariots d''urgence sont-ils complets ?","a":"Oui, nos chariots sont livrés avec tout le matériel nécessaire : défibrillateur, moniteur, aspirateur, oxygène et médicaments d''urgence."},{"q":"Proposez-vous une démonstration avant l’achat ?","a":"Nous organisons une démonstration dans votre service, avec vos propres cas d''usage, ou une visite de site chez un confrère déjà équipé. C''est la meilleure façon de valider l''ergonomie avec les utilisateurs finaux."},{"q":"Quelle garantie couvre ces équipements ?","a":"La garantie constructeur est de 24 mois pièces et main-d''œuvre, extensible à 60 mois. Elle couvre les défauts de fabrication et inclut les mises à jour logicielles de sécurité."},{"q":"Ces dispositifs s’intègrent-ils à notre système d’information ?","a":"Les appareils communicants sont compatibles DICOM et HL7, ce qui permet leur raccordement à un PACS ou à un dossier patient informatisé existant. Notre équipe technique valide l''interopérabilité avant la mise en production."}]', 0, 'sol-emergency', 1, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (7, 'fr', 'informatique-medicale', 'Informatique Médicale', 'DMP, télémédecine, PACS/RIS et cybersécurité HDS.', '<p>Notre département d''informatique médicale propose des solutions complètes et sécurisées pour la digitalisation et la gestion des données des établissements de santé.</p>', 'monitor', 'https://images.unsplash.com/photo-1576091160399-112ba8d25d1d?w=1920', 'indigo-500', '[]', '["Dossier Médical Partagé (DMP)","Télémédecine et téléconsultation","Solutions PACS/RIS","Cybersécurité HDS","Hébergement données santé","Applications mobiles"]', '[{"q":"Vos solutions DMP sont-elles conformes HDS ?","a":"Oui, toutes nos solutions DMP sont certifiées HDS (Hébergeur de Données de Santé) et conformes au RGPD et à la réglementation algérienne."},{"q":"Proposez-vous des solutions de télémédecine ?","a":"Oui, nous proposons des solutions complètes de téléconsultation, téléexpertise et télésurveillance avec visioconférence HD sécurisée."},{"q":"Proposez-vous une démonstration avant l’achat ?","a":"Nous organisons une démonstration dans votre service, avec vos propres cas d''usage, ou une visite de site chez un confrère déjà équipé. C''est la meilleure façon de valider l''ergonomie avec les utilisateurs finaux."},{"q":"Quelle garantie couvre ces équipements ?","a":"La garantie constructeur est de 24 mois pièces et main-d''œuvre, extensible à 60 mois. Elle couvre les défauts de fabrication et inclut les mises à jour logicielles de sécurité."},{"q":"Ces dispositifs s’intègrent-ils à notre système d’information ?","a":"Les appareils communicants sont compatibles DICOM et HL7, ce qui permet leur raccordement à un PACS ou à un dossier patient informatisé existant. Notre équipe technique valide l''interopérabilité avant la mise en production."}]', 0, 'sol-informatics', 1, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (8, 'fr', 'laboratoire', 'Laboratoire', 'Analyseurs d''hématologie, biochimie, microscopes et centrifugeuses.', '<p>Notre gamme de laboratoire couvre tous les besoins des laboratoires d''analyses médicales, de l''entrée de gamme au haut débit, avec une précision analytique garantie.</p>', 'flask-conical', 'https://images.unsplash.com/photo-1579154204601-01588f351e67?w=1920', 'teal-500', '[]', '["Analyseurs d''hématologie","Analyseurs de biochimie","Microscopes de laboratoire","Centrifugeuses","Étuves et incubateurs","Réactifs et consommables"]', '[{"q":"Quels types d''analyseurs proposez-vous ?","a":"Nous proposons des analyseurs d''hématologie, biochimie, immunologie et coagulation, de l''entrée de gamme au haut débit."},{"q":"Les réactifs sont-ils inclus ?","a":"Les réactifs de démarrage sont inclus avec chaque analyseur. Nous proposons ensuite des contrats de fourniture à tarifs préférentiels."},{"q":"Proposez-vous une démonstration avant l’achat ?","a":"Nous organisons une démonstration dans votre service, avec vos propres cas d''usage, ou une visite de site chez un confrère déjà équipé. C''est la meilleure façon de valider l''ergonomie avec les utilisateurs finaux."},{"q":"Quelle garantie couvre ces équipements ?","a":"La garantie constructeur est de 24 mois pièces et main-d''œuvre, extensible à 60 mois. Elle couvre les défauts de fabrication et inclut les mises à jour logicielles de sécurité."},{"q":"Ces dispositifs s’intègrent-ils à notre système d’information ?","a":"Les appareils communicants sont compatibles DICOM et HL7, ce qui permet leur raccordement à un PACS ou à un dossier patient informatisé existant. Notre équipe technique valide l''interopérabilité avant la mise en production."}]', 0, 'sol-laboratory', 1, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (9, 'fr', 'reeducation', 'Rééducation', 'Tables de kinésithérapie, électrothérapie, ultrasons thérapeutiques.', '<p>Notre département de rééducation propose des équipements professionnels et ergonomiques pour les centres de kinésithérapie et de réadaptation fonctionnelle.</p>', 'accessibility', 'https://images.unsplash.com/photo-1576091160399-112ba8d25d1d?w=1920', 'cyan-500', '[14]', '["Tables de kinésithérapie","Appareils d''électrothérapie","Ultrasons thérapeutiques","Équipements de musculation","Plateformes de marche","Matériel certifié CE"]', '[{"q":"Proposez-vous du matériel de rééducation neurologique ?","a":"Oui, nous proposons des plateformes de rééducation neurologique, des exosquelettes et des systèmes de réalité virtuelle."},{"q":"Les appareils d''électrothérapie sont-ils multifonctions ?","a":"Oui, nos appareils combinent TENS, EMS, ultrasons et laser thérapeutique dans un seul dispositif compact."},{"q":"Proposez-vous une démonstration avant l’achat ?","a":"Nous organisons une démonstration dans votre service, avec vos propres cas d''usage, ou une visite de site chez un confrère déjà équipé. C''est la meilleure façon de valider l''ergonomie avec les utilisateurs finaux."},{"q":"Quelle garantie couvre ces équipements ?","a":"La garantie constructeur est de 24 mois pièces et main-d''œuvre, extensible à 60 mois. Elle couvre les défauts de fabrication et inclut les mises à jour logicielles de sécurité."},{"q":"Ces dispositifs s’intègrent-ils à notre système d’information ?","a":"Les appareils communicants sont compatibles DICOM et HL7, ce qui permet leur raccordement à un PACS ou à un dossier patient informatisé existant. Notre équipe technique valide l''interopérabilité avant la mise en production."}]', 0, 'sol-rehabilitation', 1, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (1001, 'en', 'diagnostic-imaging', 'Diagnostic & Imaging', 'Ultrasound machines, blood pressure monitors, stethoscopes and high-precision diagnostic equipment.', '<p>Our range of diagnostic and imaging solutions is designed to provide unparalleled precision to healthcare professionals. We offer CE-certified equipment compliant with ISO 13485 standards.</p><p>Whether you are a private practice or a large hospital, we have the solution tailored to your specific needs.</p>', 'stethoscope', 'https://images.unsplash.com/photo-1579154204601-01588f351e67?w=1920', 'sari-blue', '[1,4,5]', '["4D high-resolution imaging","WiFi and Bluetooth connectivity","Long battery life","CE and ISO 13485 certification","HD touch screens","Delivery and installation included"]', '[{"q":"What types of ultrasound machines do you offer?","a":"We offer portable and fixed ultrasound machines, with different probe configurations (convex, linear, endocavitary). All our devices are CE certified and ISO 13485 compliant."},{"q":"Are blood pressure monitors medically certified?","a":"Yes, all our blood pressure monitors are Class IIa medical devices, CE certified with clinical validation according to the ESH protocol."},{"q":"Do you offer training on how to use them?","a":"Yes, a basic training session is included with every purchase. Advanced training is available as an option."},{"q":"Can we see a demonstration before buying?","a":"We arrange a demonstration in your own department, using your real use cases, or a site visit to a peer already equipped. It is the best way to validate ergonomics with the end users."},{"q":"What warranty covers this equipment?","a":"The manufacturer warranty runs for 24 months, parts and labour, extendable to 60 months. It covers manufacturing defects and includes security software updates."},{"q":"Do these devices integrate with our information system?","a":"Connected devices support DICOM and HL7, so they plug into an existing PACS or electronic patient record. Our technical team validates interoperability before going live."}]', 0, 'sol-diagnostic', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (1002, 'en', 'cardiology', 'Cardiology', 'ECG, defibrillators, cardiac monitors and holters for optimal surveillance.', '<p>Cardiology requires absolute reliability. Our cardiac monitoring and defibrillation equipment is designed for both emergency situations and daily follow-up.</p>', 'heart-pulse', 'https://images.unsplash.com/photo-1559757175-5700dde675bc?w=1920', 'red-500', '[7]', '["3/5/12 lead ECG","AED and manual defibrillators","Real-time cardiac monitors","24/48/72h ECG Holters","Medical CE compliance","24/7 technical support"]', '[{"q":"Are your ECGs 12-lead?","a":"Yes, we offer 3, 6, and 12-lead ECGs according to your needs. All our ECGs feature a touch screen and an integrated thermal printer."},{"q":"Are defibrillators easy to use?","a":"Yes, all our AEDs are designed for simple use with step-by-step voice guidance and automatic rhythm analysis in under 10 seconds."},{"q":"Can we see a demonstration before buying?","a":"We arrange a demonstration in your own department, using your real use cases, or a site visit to a peer already equipped. It is the best way to validate ergonomics with the end users."},{"q":"What warranty covers this equipment?","a":"The manufacturer warranty runs for 24 months, parts and labour, extendable to 60 months. It covers manufacturing defects and includes security software updates."},{"q":"Do these devices integrate with our information system?","a":"Connected devices support DICOM and HL7, so they plug into an existing PACS or electronic patient record. Our technical team validates interoperability before going live."}]', 0, 'sol-cardiology', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (1003, 'en', 'medical-imaging', 'Medical Imaging', 'CT scanners, MRI, digital radiology and PACS/RIS solutions.', '<p>Our medical imaging solutions cover all diagnostic needs of healthcare facilities. From 16-slice CT scanners to 3T MRI, we offer state-of-the-art equipment.</p>', 'scan', 'https://images.unsplash.com/photo-1516549655169-df83a0774514?w=1920', 'purple-500', '[]', '["16 to 128 slice CT scanners","1.5T and 3T MRI","DR/CR digital radiology","PACS/RIS solutions","HDS compliance","Preventive maintenance"]', '[{"q":"Do you offer CT scanners?","a":"Yes, we offer a complete range of CT scanners, from 16 to 128 slices, with installation and training included."},{"q":"Are MRIs compatible with all patients?","a":"Yes, our MRIs are adapted to all patient profiles, including children and claustrophobic individuals."},{"q":"Can we see a demonstration before buying?","a":"We arrange a demonstration in your own department, using your real use cases, or a site visit to a peer already equipped. It is the best way to validate ergonomics with the end users."},{"q":"What warranty covers this equipment?","a":"The manufacturer warranty runs for 24 months, parts and labour, extendable to 60 months. It covers manufacturing defects and includes security software updates."},{"q":"Do these devices integrate with our information system?","a":"Connected devices support DICOM and HL7, so they plug into an existing PACS or electronic patient record. Our technical team validates interoperability before going live."}]', 0, 'sol-imagerie', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (1004, 'en', 'surgery', 'Surgery', 'Surgical instruments, autoclaves, surgical lights and operating tables.', '<p>Our surgery department offers all the equipment needed for modern operating rooms, from sterilization to lighting, including precision instruments.</p>', 'syringe', 'https://images.unsplash.com/photo-1551076805-e1869033e561?w=1920', 'green-500', '[3,9]', '["Stainless steel surgical instruments","Class B autoclaves","LED surgical lights","Electric operating tables","Certified sterilization","Maintenance and after-sales service"]', '[{"q":"Are your autoclaves Class B?","a":"Yes, all our autoclaves are Class B, compliant with European standards EN 13060, with a vacuum drying cycle and complete traceability."},{"q":"Are surgical lights LED?","a":"Yes, all our surgical lights are LED with a lifespan of 50,000 hours, a CRI > 95, and an intensity of up to 150,000 Lux."},{"q":"Can we see a demonstration before buying?","a":"We arrange a demonstration in your own department, using your real use cases, or a site visit to a peer already equipped. It is the best way to validate ergonomics with the end users."},{"q":"What warranty covers this equipment?","a":"The manufacturer warranty runs for 24 months, parts and labour, extendable to 60 months. It covers manufacturing defects and includes security software updates."},{"q":"Do these devices integrate with our information system?","a":"Connected devices support DICOM and HL7, so they plug into an existing PACS or electronic patient record. Our technical team validates interoperability before going live."}]', 0, 'sol-surgery', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (1005, 'en', 'pediatrics', 'Pediatrics', 'Neonatal incubators, pediatric scales, phototherapy and adapted equipment.', '<p>Our pediatric range is specially designed for the care of newborns and children, with adapted, secure and gentle equipment.</p>', 'baby', 'https://images.unsplash.com/photo-1583947215259-38e31be8751f?w=1920', 'pink-500', '[12]', '["Neonatal incubators","5g pediatric scales","Phototherapy lamps","Infrared thermometers","Neonatal monitors","Child-adapted equipment"]', '[{"q":"Are incubators suitable for premature babies?","a":"Yes, our incubators are suitable for premature babies from 28 weeks of gestation, with precise control of temperature, humidity, and oxygen."},{"q":"Are the scales accurate?","a":"Yes, our pediatric scales have an accuracy of 5g with a Hold function for restless babies and a Tare function for diapers."},{"q":"Can we see a demonstration before buying?","a":"We arrange a demonstration in your own department, using your real use cases, or a site visit to a peer already equipped. It is the best way to validate ergonomics with the end users."},{"q":"What warranty covers this equipment?","a":"The manufacturer warranty runs for 24 months, parts and labour, extendable to 60 months. It covers manufacturing defects and includes security software updates."},{"q":"Do these devices integrate with our information system?","a":"Connected devices support DICOM and HL7, so they plug into an existing PACS or electronic patient record. Our technical team validates interoperability before going live."}]', 0, 'sol-pediatrics', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (1006, 'en', 'emergency-resuscitation', 'Emergency & Resuscitation', 'Defibrillators, emergency carts, multiparameter monitors and suction pumps.', '<p>The emergency department requires reliable and 24/7 available equipment. Our solutions are designed for speed, robustness and efficiency in critical situations.</p>', 'activity', 'https://images.unsplash.com/photo-1516549655169-df83a0774514?w=1920', 'orange-500', '[7,15]', '["AED/Manual defibrillators","Complete emergency carts","Multiparameter monitors","Suction pumps","Syringe pumps","Guaranteed 24/7 support"]', '[{"q":"Are defibrillators automatic?","a":"Yes, we offer AEDs (semi-automatic) and fully automatic defibrillators with voice guidance and rhythm analysis in under 10 seconds."},{"q":"Are emergency carts complete?","a":"Yes, our carts are delivered with all necessary equipment: defibrillator, monitor, suction pump, oxygen, and emergency medications."},{"q":"Can we see a demonstration before buying?","a":"We arrange a demonstration in your own department, using your real use cases, or a site visit to a peer already equipped. It is the best way to validate ergonomics with the end users."},{"q":"What warranty covers this equipment?","a":"The manufacturer warranty runs for 24 months, parts and labour, extendable to 60 months. It covers manufacturing defects and includes security software updates."},{"q":"Do these devices integrate with our information system?","a":"Connected devices support DICOM and HL7, so they plug into an existing PACS or electronic patient record. Our technical team validates interoperability before going live."}]', 0, 'sol-emergency', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (1007, 'en', 'medical-informatics', 'Medical Informatics', 'EHR, telemedicine, PACS/RIS and HDS cybersecurity.', '<p>Our medical informatics department offers comprehensive and secure solutions for the digitalization and management of healthcare facility data.</p>', 'monitor', 'https://images.unsplash.com/photo-1576091160399-112ba8d25d1d?w=1920', 'indigo-500', '[]', '["Shared Medical Record (EHR)","Telemedicine and teleconsultation","PACS/RIS solutions","HDS cybersecurity","Health data hosting","Mobile applications"]', '[{"q":"Are your EHR solutions HDS compliant?","a":"Yes, all our EHR solutions are HDS certified (Health Data Host) and compliant with GDPR and Algerian regulations."},{"q":"Do you offer telemedicine solutions?","a":"Yes, we offer complete teleconsultation, tele-expertise, and remote monitoring solutions with secure HD video conferencing."},{"q":"Can we see a demonstration before buying?","a":"We arrange a demonstration in your own department, using your real use cases, or a site visit to a peer already equipped. It is the best way to validate ergonomics with the end users."},{"q":"What warranty covers this equipment?","a":"The manufacturer warranty runs for 24 months, parts and labour, extendable to 60 months. It covers manufacturing defects and includes security software updates."},{"q":"Do these devices integrate with our information system?","a":"Connected devices support DICOM and HL7, so they plug into an existing PACS or electronic patient record. Our technical team validates interoperability before going live."}]', 0, 'sol-informatics', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (1008, 'en', 'laboratory', 'Laboratory', 'Hematology analyzers, biochemistry, microscopes and centrifuges.', '<p>Our laboratory range covers all the needs of medical analysis laboratories, from entry-level to high-throughput, with guaranteed analytical precision.</p>', 'flask-conical', 'https://images.unsplash.com/photo-1579154204601-01588f351e67?w=1920', 'teal-500', '[]', '["Hematology analyzers","Biochemistry analyzers","Laboratory microscopes","Centrifuges","Ovens and incubators","Reagents and consumables"]', '[{"q":"What types of analyzers do you offer?","a":"We offer hematology, biochemistry, immunology, and coagulation analyzers, from entry-level to high-throughput."},{"q":"Are reagents included?","a":"Starter reagents are included with each analyzer. We then offer reagent supply contracts at preferential rates."},{"q":"Can we see a demonstration before buying?","a":"We arrange a demonstration in your own department, using your real use cases, or a site visit to a peer already equipped. It is the best way to validate ergonomics with the end users."},{"q":"What warranty covers this equipment?","a":"The manufacturer warranty runs for 24 months, parts and labour, extendable to 60 months. It covers manufacturing defects and includes security software updates."},{"q":"Do these devices integrate with our information system?","a":"Connected devices support DICOM and HL7, so they plug into an existing PACS or electronic patient record. Our technical team validates interoperability before going live."}]', 0, 'sol-laboratory', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (1009, 'en', 'rehabilitation', 'Rehabilitation', 'Physiotherapy tables, electrotherapy, therapeutic ultrasound.', '<p>Our rehabilitation department offers professional and ergonomic equipment for physiotherapy and functional rehabilitation centers.</p>', 'accessibility', 'https://images.unsplash.com/photo-1576091160399-112ba8d25d1d?w=1920', 'cyan-500', '[14]', '["Physiotherapy tables","Electrotherapy devices","Therapeutic ultrasound","Muscle building equipment","Walking platforms","CE certified equipment"]', '[{"q":"Do you offer neurological rehabilitation equipment?","a":"Yes, we offer neurological rehabilitation platforms, exoskeletons, and virtual reality systems."},{"q":"Are electrotherapy devices multifunctional?","a":"Yes, our devices combine TENS, EMS, ultrasound, and therapeutic laser in a single compact device."},{"q":"Can we see a demonstration before buying?","a":"We arrange a demonstration in your own department, using your real use cases, or a site visit to a peer already equipped. It is the best way to validate ergonomics with the end users."},{"q":"What warranty covers this equipment?","a":"The manufacturer warranty runs for 24 months, parts and labour, extendable to 60 months. It covers manufacturing defects and includes security software updates."},{"q":"Do these devices integrate with our information system?","a":"Connected devices support DICOM and HL7, so they plug into an existing PACS or electronic patient record. Our technical team validates interoperability before going live."}]', 0, 'sol-rehabilitation', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (2001, 'ar', 'التشخيص-والتصوير', 'التشخيص والتصوير', 'أجهزة الموجات فوق الصوتية وأجهزة قياس الضغط والسماعات ومعدات التشخيص عالية الدقة.', '<p>تم تصميم مجموعة حلول التشخيص والتصوير لدينا لتقديم دقة لا مثيل لها للمهنيين الصحيين. نقدم معدات حاصلة على شهادة CE ومتوافقة مع معايير ISO 13485.</p><p>سواء كنت عيادة خاصة أو مستشفى كبير، لدينا الحل المناسب لاحتياجاتك المحددة.</p>', 'stethoscope', 'https://images.unsplash.com/photo-1579154204601-01588f351e67?w=1920', 'sari-blue', '[1,4,5]', '["تصوير عالي الدقة 4D","اتصال WiFi و Bluetooth","عمر بطارية طويل","شهادة CE و ISO 13485","شاشات تعمل باللمس HD","التوصيل والتركيب مشمولان"]', '[{"q":"ما أنواع أجهزة الموجات فوق الصوتية التي تقدمونها؟","a":"نقدم أجهزة محمولة وثابتة، مع تكوينات مختلفة للمسابر (محدبة، خطية، تجويفية). جميع أجهزتنا حاصلة على شهادة CE ومتوافقة مع ISO 13485."},{"q":"هل أجهزة قياس ضغط الدم معتمدة طبياً؟","a":"نعم، جميع أجهزة قياس ضغط الدم لدينا هي أجهزة طبية من الفئة IIa، حاصلة على شهادة CE مع التحقق السريري وفقاً لبروتوكول ESH."},{"q":"هل تقدمون تدريباً على الاستخدام؟","a":"نعم، جلسة تدريب أساسية مشمولة مع كل عملية شراء. التدريب المتقدم متاح كخيار."},{"q":"هل تقدمون عرضًا توضيحيًا قبل الشراء؟","a":"ننظم عرضًا توضيحيًا داخل مصلحتكم باستخدام حالاتكم الفعلية، أو زيارة ميدانية لمؤسسة زميلة مجهزة بالفعل، وهي أفضل وسيلة للتحقق من سهولة الاستعمال مع المستخدمين النهائيين."},{"q":"ما هو الضمان الذي يغطي هذه المعدات؟","a":"ضمان المصنّع 24 شهرًا يشمل القطع واليد العاملة، وقابل للتمديد إلى 60 شهرًا. يغطي عيوب التصنيع ويتضمن تحديثات البرمجيات الأمنية."},{"q":"هل تندمج هذه الأجهزة مع نظام المعلومات لدينا؟","a":"الأجهزة المتصلة متوافقة مع معياري DICOM وHL7، ما يسمح بربطها بنظام PACS أو بملف المريض الإلكتروني القائم. ويتحقق فريقنا التقني من التشغيل البيني قبل الإنتاج."}]', 0, 'sol-diagnostic', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (2002, 'ar', 'أمراض-القلب', 'أمراض القلب', 'تخطيط القلب وأجهزة إزالة الرجفان وشاشات القلب وهولتر للمراقبة المثلى.', '<p>تتطلب أمراض القلب موثوقية مطلقة. تم تصميم معدات مراقبة القلب وإزالة الرجفان لدينا لحالات الطوارئ وكذلك للمراقبة اليومية.</p>', 'heart-pulse', 'https://images.unsplash.com/photo-1559757175-5700dde675bc?w=1920', 'red-500', '[7]', '["تخطيط القلب 3/5/12 قطب","أجهزة إزالة الرجفان AED و DSA","شاشات القلب في الوقت الفعلي","هولتر ECG 24/48/72 ساعة","امتثال CE الطبي","دعم فني 24/7"]', '[{"q":"هل أجهزة تخطيط القلب 12 قطب؟","a":"نعم، نقدم أجهزة تخطيط قلب 3 و 6 و 12 قطب حسب احتياجاتك. جميع أجهزة تخطيط القلب لدينا مزودة بشاشة لمس وطابعة حرارية مدمجة."},{"q":"هل أجهزة إزالة الرجفان سهلة الاستخدام؟","a":"نعم، جميع أجهزة AED لدينا مصممة للاستخدام البسيط مع إرشادات صوتية خطوة بخطوة وتحليل تلقائي للإيقاع في أقل من 10 ثوانٍ."},{"q":"هل تقدمون عرضًا توضيحيًا قبل الشراء؟","a":"ننظم عرضًا توضيحيًا داخل مصلحتكم باستخدام حالاتكم الفعلية، أو زيارة ميدانية لمؤسسة زميلة مجهزة بالفعل، وهي أفضل وسيلة للتحقق من سهولة الاستعمال مع المستخدمين النهائيين."},{"q":"ما هو الضمان الذي يغطي هذه المعدات؟","a":"ضمان المصنّع 24 شهرًا يشمل القطع واليد العاملة، وقابل للتمديد إلى 60 شهرًا. يغطي عيوب التصنيع ويتضمن تحديثات البرمجيات الأمنية."},{"q":"هل تندمج هذه الأجهزة مع نظام المعلومات لدينا؟","a":"الأجهزة المتصلة متوافقة مع معياري DICOM وHL7، ما يسمح بربطها بنظام PACS أو بملف المريض الإلكتروني القائم. ويتحقق فريقنا التقني من التشغيل البيني قبل الإنتاج."}]', 0, 'sol-cardiology', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (2003, 'ar', 'التصوير-الطبي', 'التصوير الطبي', 'أجهزة التصوير المقطعي والرنين المغناطيسي والأشعة الرقمية وحلول PACS/RIS.', '<p>تغطي حلول التصوير الطبي لدينا جميع الاحتياجات التشخيصية للمرافق الصحية. من الماسحات الضوئية 16 شريحة إلى الرنين المغناطيسي 3T، نقدم معدات من أحدث جيل.</p>', 'scan', 'https://images.unsplash.com/photo-1516549655169-df83a0774514?w=1920', 'purple-500', '[]', '["أجهزة التصوير المقطعي 16 إلى 128 شريحة","الرنين المغناطيسي 1.5T و 3T","الأشعة الرقمية DR/CR","حلول PACS/RIS","امتثال HDS","الصيانة الوقائية"]', '[{"q":"هل تقدمون أجهزة التصوير المقطعي؟","a":"نعم، نقدم مجموعة كاملة من أجهزة التصوير المقطعي، من 16 إلى 128 شريحة، مع التركيب والتدريب المشمولين."},{"q":"هل أجهزة الرنين المغناطيسي متوافقة مع جميع المرضى؟","a":"نعم، أجهزة الرنين المغناطيسي لدينا متكيفة مع جميع ملفات المرضى، بما في ذلك الأطفال والأشخاص الذين يعانون من رهاب الأماكن المغلقة."},{"q":"هل تقدمون عرضًا توضيحيًا قبل الشراء؟","a":"ننظم عرضًا توضيحيًا داخل مصلحتكم باستخدام حالاتكم الفعلية، أو زيارة ميدانية لمؤسسة زميلة مجهزة بالفعل، وهي أفضل وسيلة للتحقق من سهولة الاستعمال مع المستخدمين النهائيين."},{"q":"ما هو الضمان الذي يغطي هذه المعدات؟","a":"ضمان المصنّع 24 شهرًا يشمل القطع واليد العاملة، وقابل للتمديد إلى 60 شهرًا. يغطي عيوب التصنيع ويتضمن تحديثات البرمجيات الأمنية."},{"q":"هل تندمج هذه الأجهزة مع نظام المعلومات لدينا؟","a":"الأجهزة المتصلة متوافقة مع معياري DICOM وHL7، ما يسمح بربطها بنظام PACS أو بملف المريض الإلكتروني القائم. ويتحقق فريقنا التقني من التشغيل البيني قبل الإنتاج."}]', 0, 'sol-imagerie', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (2004, 'ar', 'الجراحة', 'الجراحة', 'أدوات جراحية وأجهزة تعقيم ومصابيح جراحية وطاولات عمليات.', '<p>يقدم قسم الجراحة لدينا جميع المعدات اللازمة لغرف العمليات الحديثة، من التعقيم إلى الإضاءة، مروراً بالأدوات الدقيقة.</p>', 'syringe', 'https://images.unsplash.com/photo-1551076805-e1869033e561?w=1920', 'green-500', '[3,9]', '["أدوات جراحية من الفولاذ المقاوم للصدأ","أجهزة تعقيم من الفئة B","مصابيح جراحية LED","طاولات عمليات كهربائية","تعقيم معتمد","الصيانة وخدمة ما بعد البيع"]', '[{"q":"هل أجهزة التعقيم من الفئة B؟","a":"نعم، جميع أجهزة التعقيم لدينا من الفئة B، متوافقة مع المعايير الأوروبية EN 13060، مع دورة تجفيف تحت الفراغ وتتبع كامل."},{"q":"هل المصابيح الجراحية LED؟","a":"نعم، جميع مصابيحنا الجراحية LED بعمر افتراضي 50,000 ساعة، ومؤشر تجسيد اللون > 95، وشدة تصل إلى 150,000 لوكس."},{"q":"هل تقدمون عرضًا توضيحيًا قبل الشراء؟","a":"ننظم عرضًا توضيحيًا داخل مصلحتكم باستخدام حالاتكم الفعلية، أو زيارة ميدانية لمؤسسة زميلة مجهزة بالفعل، وهي أفضل وسيلة للتحقق من سهولة الاستعمال مع المستخدمين النهائيين."},{"q":"ما هو الضمان الذي يغطي هذه المعدات؟","a":"ضمان المصنّع 24 شهرًا يشمل القطع واليد العاملة، وقابل للتمديد إلى 60 شهرًا. يغطي عيوب التصنيع ويتضمن تحديثات البرمجيات الأمنية."},{"q":"هل تندمج هذه الأجهزة مع نظام المعلومات لدينا؟","a":"الأجهزة المتصلة متوافقة مع معياري DICOM وHL7، ما يسمح بربطها بنظام PACS أو بملف المريض الإلكتروني القائم. ويتحقق فريقنا التقني من التشغيل البيني قبل الإنتاج."}]', 0, 'sol-surgery', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (2005, 'ar', 'طب-الأطفال', 'طب الأطفال', 'حاضنات لحديثي الولادة وموازين طب الأطفال والعلاج الضوئي ومعدات متكيفة.', '<p>مجموعة طب الأطفال لدينا مصممة خصيصاً لرعاية حديثي الولادة والأطفال، مع معدات متكيفة وآمنة ولطيفة.</p>', 'baby', 'https://images.unsplash.com/photo-1583947215259-38e31be8751f?w=1920', 'pink-500', '[12]', '["حاضنات لحديثي الولادة","موازين طب الأطفال 5 جرام","مصابيح العلاج الضوئي","مقاييس الحرارة بالأشعة تحت الحمراء","شاشات حديثي الولادة","معدات متكيفة مع الأطفال"]', '[{"q":"هل الحاضنات مناسبة للأطفال الخدج؟","a":"نعم، حاضناتنا مناسبة للأطفال الخدج من 28 أسبوعاً من الحمل، مع تحكم دقيق في درجة الحرارة والرطوبة والأكسجين."},{"q":"هل الموازين دقيقة؟","a":"نعم، موازين طب الأطفال لدينا بدقة 5 جرام مع وظيفة الإمساك (Hold) للأطفال غير الهادئين ووظيفة الوزن الصافي للحفاضات."},{"q":"هل تقدمون عرضًا توضيحيًا قبل الشراء؟","a":"ننظم عرضًا توضيحيًا داخل مصلحتكم باستخدام حالاتكم الفعلية، أو زيارة ميدانية لمؤسسة زميلة مجهزة بالفعل، وهي أفضل وسيلة للتحقق من سهولة الاستعمال مع المستخدمين النهائيين."},{"q":"ما هو الضمان الذي يغطي هذه المعدات؟","a":"ضمان المصنّع 24 شهرًا يشمل القطع واليد العاملة، وقابل للتمديد إلى 60 شهرًا. يغطي عيوب التصنيع ويتضمن تحديثات البرمجيات الأمنية."},{"q":"هل تندمج هذه الأجهزة مع نظام المعلومات لدينا؟","a":"الأجهزة المتصلة متوافقة مع معياري DICOM وHL7، ما يسمح بربطها بنظام PACS أو بملف المريض الإلكتروني القائم. ويتحقق فريقنا التقني من التشغيل البيني قبل الإنتاج."}]', 0, 'sol-pediatrics', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (2006, 'ar', 'الطوارئ-والإنعاش', 'الطوارئ والإنعاش', 'أجهزة إزالة الرجفان وعربات الطوارئ وشاشات متعددة المعلمات ومضخات المحاقن.', '<p>يتطلب قسم الطوارئ معدات موثوقة ومتاحة على مدار الساعة. تم تصميم حلولنا للسرعة والمتانة والكفاءة في الحالات الحرجة.</p>', 'activity', 'https://images.unsplash.com/photo-1516549655169-df83a0774514?w=1920', 'orange-500', '[7,15]', '["أجهزة إزالة الرجفان AED/DSA","عربات طوارئ كاملة","شاشات متعددة المعلمات","أجهزة شفط الإفرازات","مضخات المحاقن","دعم 24/7 مضمون"]', '[{"q":"هل أجهزة إزالة الرجفان تلقائية؟","a":"نعم، نقدم أجهزة DSA (شبه تلقائية) و DAE (تلقائية بالكامل) مع إرشادات صوتية وتحليل الإيقاع في أقل من 10 ثوانٍ."},{"q":"هل عربات الطوارئ كاملة؟","a":"نعم، يتم تسليم عرباتنا مع جميع المعدات اللازمة: جهاز صدمات، شاشة مراقبة، جهاز شفط، أكسجين، وأدوية الطوارئ."},{"q":"هل تقدمون عرضًا توضيحيًا قبل الشراء؟","a":"ننظم عرضًا توضيحيًا داخل مصلحتكم باستخدام حالاتكم الفعلية، أو زيارة ميدانية لمؤسسة زميلة مجهزة بالفعل، وهي أفضل وسيلة للتحقق من سهولة الاستعمال مع المستخدمين النهائيين."},{"q":"ما هو الضمان الذي يغطي هذه المعدات؟","a":"ضمان المصنّع 24 شهرًا يشمل القطع واليد العاملة، وقابل للتمديد إلى 60 شهرًا. يغطي عيوب التصنيع ويتضمن تحديثات البرمجيات الأمنية."},{"q":"هل تندمج هذه الأجهزة مع نظام المعلومات لدينا؟","a":"الأجهزة المتصلة متوافقة مع معياري DICOM وHL7، ما يسمح بربطها بنظام PACS أو بملف المريض الإلكتروني القائم. ويتحقق فريقنا التقني من التشغيل البيني قبل الإنتاج."}]', 0, 'sol-emergency', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (2007, 'ar', 'المعلوماتية-الطبية', 'المعلوماتية الطبية', 'السجل الطبي المشترك والطب عن بعد وحلول PACS/RIS والأمن السيبراني HDS.', '<p>يقدم قسم المعلوماتية الطبية لدينا حلولاً شاملة وآمنة لرقمنة وإدارة بيانات المرافق الصحية.</p>', 'monitor', 'https://images.unsplash.com/photo-1576091160399-112ba8d25d1d?w=1920', 'indigo-500', '[]', '["السجل الطبي المشترك (DMP)","الطب عن بعد والاستشارة عن بعد","حلول PACS/RIS","أمن سيبراني HDS","استضافة بيانات الصحة","تطبيقات الجوال"]', '[{"q":"هل حلول السجل الطبي متوافقة مع HDS؟","a":"نعم، جميع حلول السجل الطبي لدينا معتمدة من HDS (مضيف بيانات الصحة) ومتوافقة مع GDPR واللوائح الجزائرية."},{"q":"هل تقدمون حلول الطب عن بعد؟","a":"نعم، نقدم حلولاً كاملة للاستشارة عن بعد، والخبرة عن بعد، والمراقبة عن بعد مع مؤتمرات فيديو عالية الدقة وآمنة."},{"q":"هل تقدمون عرضًا توضيحيًا قبل الشراء؟","a":"ننظم عرضًا توضيحيًا داخل مصلحتكم باستخدام حالاتكم الفعلية، أو زيارة ميدانية لمؤسسة زميلة مجهزة بالفعل، وهي أفضل وسيلة للتحقق من سهولة الاستعمال مع المستخدمين النهائيين."},{"q":"ما هو الضمان الذي يغطي هذه المعدات؟","a":"ضمان المصنّع 24 شهرًا يشمل القطع واليد العاملة، وقابل للتمديد إلى 60 شهرًا. يغطي عيوب التصنيع ويتضمن تحديثات البرمجيات الأمنية."},{"q":"هل تندمج هذه الأجهزة مع نظام المعلومات لدينا؟","a":"الأجهزة المتصلة متوافقة مع معياري DICOM وHL7، ما يسمح بربطها بنظام PACS أو بملف المريض الإلكتروني القائم. ويتحقق فريقنا التقني من التشغيل البيني قبل الإنتاج."}]', 0, 'sol-informatics', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (2008, 'ar', 'المختبر', 'المختبر', 'أجهزة تحليل الدم والكيمياء الحيوية والمجاهر وأجهزة الطرد المركزي.', '<p>تغطي مجموعة المختبر لدينا جميع احتياجات مختبرات التحاليل الطبية، من مستوى الدخول إلى الإنتاج العالي، مع ضمان الدقة التحليلية.</p>', 'flask-conical', 'https://images.unsplash.com/photo-1579154204601-01588f351e67?w=1920', 'teal-500', '[]', '["أجهزة تحليل الدم","أجهزة تحليل الكيمياء الحيوية","مجاهر المختبر","أجهزة الطرد المركزي","أفران وحاضنات","الكواشف والمواد الاستهلاكية"]', '[{"q":"ما أنواع أجهزة التحليل التي تقدمونها؟","a":"نقدم أجهزة تحليل الدم، والكيمياء الحيوية، والمناعة، والتخثر، من مستوى الدخول إلى الإنتاج العالي."},{"q":"هل الكواشف مشمولة؟","a":"الكواشف الأولية مشمولة مع كل جهاز تحليل. نحن نقدم بعد ذلك عقود توريد الكواشف بأسعار تفضيلية."},{"q":"هل تقدمون عرضًا توضيحيًا قبل الشراء؟","a":"ننظم عرضًا توضيحيًا داخل مصلحتكم باستخدام حالاتكم الفعلية، أو زيارة ميدانية لمؤسسة زميلة مجهزة بالفعل، وهي أفضل وسيلة للتحقق من سهولة الاستعمال مع المستخدمين النهائيين."},{"q":"ما هو الضمان الذي يغطي هذه المعدات؟","a":"ضمان المصنّع 24 شهرًا يشمل القطع واليد العاملة، وقابل للتمديد إلى 60 شهرًا. يغطي عيوب التصنيع ويتضمن تحديثات البرمجيات الأمنية."},{"q":"هل تندمج هذه الأجهزة مع نظام المعلومات لدينا؟","a":"الأجهزة المتصلة متوافقة مع معياري DICOM وHL7، ما يسمح بربطها بنظام PACS أو بملف المريض الإلكتروني القائم. ويتحقق فريقنا التقني من التشغيل البيني قبل الإنتاج."}]', 0, 'sol-laboratory', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (2009, 'ar', 'إعادة-التأهيل', 'إعادة التأهيل', 'طاولات العلاج الطبيعي والعلاج الكهربائي والموجات فوق الصوتية ومعدات التمارين.', '<p>يقدم قسم إعادة التأهيل لدينا معدات احترافية ومريحة لمراكز العلاج الطبيعي وإعادة التأهيل الوظيفي.</p>', 'accessibility', 'https://images.unsplash.com/photo-1576091160399-112ba8d25d1d?w=1920', 'cyan-500', '[14]', '["طاولات العلاج الطبيعي","أجهزة العلاج الكهربائي","الموجات فوق الصوتية العلاجية","معدات التمارين","منصات المشي","معدات معتمدة CE"]', '[{"q":"هل تقدمون معدات إعادة التأهيل العصبي؟","a":"نعم، نقدم منصات إعادة التأهيل العصبي، والهياكل الخارجية، وأنظمة الواقع الافتراضي."},{"q":"هل أجهزة العلاج الكهربائي متعددة الوظائف؟","a":"نعم، تجمع أجهزتنا بين TENS و EMS والموجات فوق الصوتية والليزر العلاجي في جهاز واحد مدمج."},{"q":"هل تقدمون عرضًا توضيحيًا قبل الشراء؟","a":"ننظم عرضًا توضيحيًا داخل مصلحتكم باستخدام حالاتكم الفعلية، أو زيارة ميدانية لمؤسسة زميلة مجهزة بالفعل، وهي أفضل وسيلة للتحقق من سهولة الاستعمال مع المستخدمين النهائيين."},{"q":"ما هو الضمان الذي يغطي هذه المعدات؟","a":"ضمان المصنّع 24 شهرًا يشمل القطع واليد العاملة، وقابل للتمديد إلى 60 شهرًا. يغطي عيوب التصنيع ويتضمن تحديثات البرمجيات الأمنية."},{"q":"هل تندمج هذه الأجهزة مع نظام المعلومات لدينا؟","a":"الأجهزة المتصلة متوافقة مع معياري DICOM وHL7، ما يسمح بربطها بنظام PACS أو بملف المريض الإلكتروني القائم. ويتحقق فريقنا التقني من التشغيل البيني قبل الإنتاج."}]', 0, 'sol-rehabilitation', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3))
INSERT INTO `products` (`id`, `locale`, `slug`, `name`, `category`, `price`, `shortDesc`, `fullDesc`, `image`, `gallery`, `inStock`, `currency`, `sortOrder`, `deliveryTime`, `features`, `specs`, `options`, `catalogPdf`, `legacyId`, `isDefault`, `status`, `createdAt`, `updatedAt`)
VALUES
  (1, 'fr', 'echographe-portable-pro-x1', 'Échographe Portable Pro X1', 'Diagnostic', 'Sur devis', 'Échographe haute résolution pour imagerie médicale portable', '<p>L''Échographe Portable Pro X1 représente l''excellence en matière d''imagerie médicale mobile. Doté d''un écran tactile HD de 15 pouces et de sondes multifréquences interchangeables, cet appareil offre une qualité d''image exceptionnelle comparable aux échographes fixes.</p><h3>Caractéristiques principales</h3><ul><li>Écran tactile de 15 pouces avec résolution 1920x1080</li><li>Portabilité optimisée (poids : 3,2 kg)</li><li>Autonomie de 6 heures avec batterie intégrée</li><li>Connectivité Wi-Fi et Bluetooth pour transfert de données</li><li>Compatible DICOM pour intégration PACS</li></ul><h3>Applications cliniques</h3><p>Idéal pour les consultations à domicile, les interventions en milieu rural, les services d''urgence et les cabinets médicaux mobiles.</p>', 'https://images.unsplash.com/photo-1579154204601-01588f351e67?w=800', '["https://images.unsplash.com/photo-1579154204601-01588f351e67?w=800","https://images.unsplash.com/photo-1516549655169-df83a0774514?w=800","https://images.unsplash.com/photo-1551076805-e1869033e561?w=800","https://images.unsplash.com/photo-1576091160399-112ba8d25d1d?w=800"]', 1, 'DZD', 1, '2-3 semaines', '["Imagerie 4D en temps réel","Mode Doppler couleur et pulsé","Mesures automatiques avancées","Export DICOM compatible","Interface multilingue"]', '{"Écran":"15 pouces tactile HD","Poids":"3.2 kg","Autonomie":"6 heures","Sondes":"4 sondes incluses","Connectivité":"WiFi, Bluetooth, USB-C","Résolution":"Full HD 1920x1080"}', '[{"name":"Configuration","choices":["Standard","Pro (Sondes supplémentaires)"]},{"name":"Garantie","choices":["2 ans","3 ans","5 ans"]}]', '#', 'prd-1', 1, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (2, 'fr', 'lit-examen-electrique-premium', 'Lit d''Examen Électrique Premium', 'Équipements', '2 450 € HT', 'Lit médicalisé électrique réglable en hauteur', '<p>Le Lit d''Examen Électrique Premium offre un confort optimal pour vos patients et une ergonomie parfaite pour les praticiens. Ses moteurs silencieux permettent un réglage fluide de la hauteur et de l''inclinaison du dossier.</p><h3>Confort et sécurité</h3><ul><li>Revêtement en simili-cuir antibactérien</li><li>Roues de transport verrouillables</li><li>Système anti-pincement intégré</li><li>Charge maximale : 250 kg</li></ul>', 'https://images.unsplash.com/photo-1519494026892-88bb237b200d?w=800', '["https://images.unsplash.com/photo-1519494026892-88bb237b200d?w=800","https://images.unsplash.com/photo-1584982751601-97dcc096659c?w=800","https://images.unsplash.com/photo-1576091160399-112ba8d25d1d?w=800"]', 1, 'DZD', 2, '1-2 semaines', '["Télécommande filaire ergonomique","Système anti-pincement","Roues de transport verrouillables","Certification médicale CE","Réglage mémoire de position"]', '{"Charge maximale":"250 kg","Hauteur":"45-95 cm","Dimensions":"190 x 70 cm","Moteurs":"2 moteurs électriques silencieux","Poids":"85 kg","Certification":"CE médical"}', '[{"name":"Revêtement","choices":["Simili-cuir Bleu","Simili-cuir Gris","Simili-cuir Noir"]},{"name":"Accessoires","choices":["Standard","Avec coussin cervical","Pack complet"]}]', '#', 'prd-2', 1, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (3, 'fr', 'sterilisateur-autoclave-classe-b', 'Stérilisateur Autoclave Classe B', 'Chirurgie', '3 890 € HT', 'Autoclave 23L pour stérilisation instruments médicaux', '<p>Autoclave de classe B conforme aux normes européennes pour la stérilisation de tous types d''instruments médicaux, y compris les instruments creux et poreux. Cycle automatique complet avec séchage sous vide.</p><h3>Technologie de pointe</h3><ul><li>Imprimante thermique intégrée pour la traçabilité</li><li>Écran LCD tactile intuitif</li><li>12 programmes prédéfinis</li><li>Tests automatiques Bowie-Dick</li></ul>', 'https://images.unsplash.com/photo-1583947215259-38e31be8751f?w=800', '["https://images.unsplash.com/photo-1583947215259-38e31be8751f?w=800","https://images.unsplash.com/photo-1576091160399-112ba8d25d1d?w=800"]', 0, 'DZD', 3, '4-6 semaines', '["Cycle de séchage sous vide","Imprimante thermique intégrée","Tests automatiques Bowie-Dick","Écran LCD tactile","Traçabilité complète"]', '{"Capacité":"23 litres","Pression":"2.3 bars","Température":"134°C","Cycle":"15-25 minutes","Dimensions":"45 x 55 x 45 cm","Poids":"65 kg"}', '[{"name":"Capacité","choices":["18L","23L","30L"]},{"name":"Imprimante","choices":["Avec imprimante","Sans imprimante"]}]', '#', 'prd-3', 1, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (4, 'fr', 'tensiometre-digital-pro', 'Tensiomètre Digital Pro', 'Diagnostic', '189 € HT', 'Tensiomètre professionnel avec mémoire 120 mesures', '<p>Tensiomètre digital professionnel de haute précision avec brassard universel adapté à tous les bras. Mémoire de 120 mesures avec horodatage pour un suivi optimal.</p><h3>Fonctionnalités avancées</h3><ul><li>Détection des battements irréguliers</li><li>Indicateur de positionnement du brassard</li><li>Connectivité Bluetooth pour transfert des données</li><li>Application mobile dédiée</li></ul>', 'https://images.unsplash.com/photo-1579684385127-1ef15d508118?w=800', '["https://images.unsplash.com/photo-1579684385127-1ef15d508118?w=800","https://images.unsplash.com/photo-1584982751601-97dcc096659c?w=800"]', 1, 'DZD', 4, '3-5 jours', '["Détection arythmie","Indicateur OMS coloré","Moyenne automatique","Application mobile dédiée","Brassard universel inclus"]', '{"Précision":"±3 mmHg","Mémoire":"120 mesures","Brassard":"22-42 cm","Alimentation":"4 piles AA ou secteur","Connectivité":"Bluetooth 5.0","Poids":"380 g"}', '[{"name":"Brassard","choices":["Standard (22-32cm)","Large (32-42cm)"]}]', '#', 'prd-4', 1, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (5, 'fr', 'microscope-binoculaire-led', 'Microscope Binoculaire LED', 'Diagnostic', '1 290 € HT', 'Microscope binoculaire avec éclairage LED 40x-2000x', '<p>Microscope binoculaire professionnel avec éclairage LED longue durée et système optique achromatique. Grossissement de 40x à 2000x avec 4 objectifs interchangeables.</p><h3>Optique de qualité</h3><ul><li>Système optique achromatique corrigé</li><li>Tête binoculaire inclinable 30°</li><li>Mise au point coaxiale précise</li><li>Platine mécanique avec butées de sécurité</li></ul>', 'https://images.unsplash.com/photo-1576091160399-112ba8d25d1d?w=800', '["https://images.unsplash.com/photo-1576091160399-112ba8d25d1d?w=800","https://images.unsplash.com/photo-1516549655169-df83a0774514?w=800"]', 1, 'DZD', 5, '1 semaine', '["Éclairage LED 50 000h","Système optique achromatique","Platine mécanique précise","Tête binoculaire inclinable 30°","Valise de transport incluse"]', '{"Grossissement":"40x - 2000x","Objectifs":"4x, 10x, 40x, 100x","Oculaires":"WF10x/18mm","Éclairage":"LED 3W","Poids":"6.5 kg"}', '[{"name":"Objectifs","choices":["4 objectifs (4x,10x,40x,100x)","5 objectifs (+20x)"]}]', '#', 'prd-5', 1, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (6, 'fr', 'pack-consommables-starter', 'Pack Consommables Starter', 'Consommables', '299 € HT', 'Pack de démarrage avec gants, masques et désinfectants', '<p>Pack complet de consommables médicaux pour démarrer ou réapprovisionner votre cabinet. Contient 10 boîtes de gants nitrile, masques chirurgicaux type IIR, gel hydroalcoolique et compresses stériles.</p><h3>Contenu détaillé</h3><ul><li>1000 gants nitrile sans latex ni poudre</li><li>50 masques chirurgicaux 3 plis haute filtration</li><li>5L de gel hydroalcoolique</li><li>500 compresses stériles non tissées</li></ul>', 'https://images.unsplash.com/photo-1584982751601-97dcc096659c?w=800', '["https://images.unsplash.com/photo-1584982751601-97dcc096659c?w=800","https://images.unsplash.com/photo-1584483766114-2cea6fac255f?w=800"]', 1, 'DZD', 6, '24-48h', '["Gants sans latex ni poudre","Masques 3 plis haute filtration","Gel avec agents hydratants","Compresses non tissées","Livraison rapide"]', '{"Gants":"1000 unités nitrile","Masques":"50 type IIR","Gel":"5L hydroalcoolique","Compresses":"500 stériles","Validité":"24 mois"}', '[{"name":"Taille Gants","choices":["S","M","L","XL","Mixte"]}]', '#', 'prd-6', 1, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (7, 'fr', 'defibrillateur-semi-automatique', 'Défibrillateur Semi-Automatique', 'Urgence', '1 850 € HT', 'DSA avec guide vocal et analyse rapide du rythme', '<p>Défibrillateur Semi-Automatique (DSA) de dernière génération avec guide vocal clair et analyse rapide du rythme cardiaque. Conçu pour une utilisation par les professionnels de santé et les secouristes formés.</p><h3>Simplicité d''utilisation</h3><ul><li>Guide vocal pas à pas en français</li><li>Analyse du rythme en moins de 10 secondes</li><li>Électrodes pré-gélifiées à usage unique</li><li>Autotest quotidien automatique</li></ul>', 'https://images.unsplash.com/photo-1516549655169-df83a0774514?w=800', '["https://images.unsplash.com/photo-1516549655169-df83a0774514?w=800","https://images.unsplash.com/photo-1551076805-e1869033e561?w=800"]', 1, 'DZD', 7, '1 semaine', '["Guide vocal en français","Analyse rapide du rythme","Autotest quotidien","Électrodes pédiatriques disponibles","Garantie 8 ans"]', '{"Poids":"2.1 kg","Batterie":"Lithium, 4 ans","Énergie":"150-200J","Analyse":"Moins de 10 secondes","Étanchéité":"IP55"}', '[{"name":"Pack","choices":["Appareil seul","Pack complet avec armoire","Pack formation inclus"]}]', '#', 'prd-7', 1, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (8, 'fr', 'concentrateur-oxygene-5l', 'Concentrateur d''Oxygène 5L', 'Respiratoire', '890 € HT', 'Concentrateur d''oxygène médical silencieux 5L/min', '<p>Concentrateur d''oxygène médical de haute qualité délivrant jusqu''à 5 litres par minute d''oxygène à 93% de pureté. Fonctionnement silencieux idéal pour une utilisation à domicile ou en cabinet.</p><h3>Performance</h3><ul><li>Débit réglable de 0.5 à 5 L/min</li><li>Pureté d''oxygène : 93% ±3%</li><li>Niveau sonore : moins de 40 dB</li><li>Alarme de pression et de pureté</li></ul>', 'https://images.unsplash.com/photo-1584483766114-2cea6fac255f?w=800', '["https://images.unsplash.com/photo-1584483766114-2cea6fac255f?w=800","https://images.unsplash.com/photo-1579684385127-1ef15d508118?w=800"]', 1, 'DZD', 8, '3-5 jours', '["Fonctionnement silencieux","Alarme de sécurité","Humidificateur inclus","Filtre facile à remplacer","Roulettes de transport"]', '{"Débit":"0.5-5 L/min","Pureté":"93% ±3%","Bruit":"<40 dB","Puissance":"350W","Poids":"15 kg"}', '[{"name":"Accessoires","choices":["Pack standard","Pack avec chariot","Pack complet avec masque"]}]', '#', 'prd-8', 1, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (9, 'fr', 'lampe-scialytique-mobile-led', 'Lampe Scialytique Mobile LED', 'Chirurgie', '3 200 € HT', 'Éclairage chirurgical mobile haute intensité sans ombre', '<p>Lampe scialytique mobile LED de haute performance offrant un éclairage chirurgical intense et sans ombre. Technologie LED dernière génération avec durée de vie de 50 000 heures.</p><h3>Éclairage professionnel</h3><ul><li>Intensité lumineuse : 100 000 à 150 000 Lux</li><li>Température de couleur : 4500K (lumière du jour)</li><li>IRC > 95 (restitution des couleurs)</li><li>Système anti-ombre multi-LED</li></ul>', 'https://images.unsplash.com/photo-1551076805-e1869033e561?w=800', '["https://images.unsplash.com/photo-1551076805-e1869033e561?w=800","https://images.unsplash.com/photo-1519494026892-88bb237b200d?w=800"]', 1, 'DZD', 9, '2 semaines', '["Technologie LED 50 000h","Éclairage sans ombre","Température de couleur réglable","Stérilisable","Pied mobile avec roulettes"]', '{"Intensité":"100 000-150 000 Lux","Température couleur":"4500K","IRC":">95","Durée de vie LED":"50 000h","Poids":"12 kg"}', '[{"name":"Puissance","choices":["100 000 Lux","150 000 Lux"]},{"name":"Installation","choices":["Mobile sur pied","Plafonnier fixe"]}]', '#', 'prd-9', 1, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (10, 'fr', 'pousse-seringue-electrique-double', 'Pousse-Seringue Électrique Double', 'Soins Intensifs', '1 450 € HT', 'Infusion de précision avec alarmes de sécurité', '<p>Pousse-seringue électrique double canal pour administration précise de médicaments en soins intensifs et réanimation. Système de sécurité avancé avec multiples alarmes.</p><h3>Précision et sécurité</h3><ul><li>Débit : 0.1 à 1200 mL/h</li><li>Précision : ±2%</li><li>Alarmes : occlusion, fin de perfusion, batterie faible</li><li>Compatible avec seringues de 10 à 60 mL</li></ul>', 'https://images.unsplash.com/photo-1519494026892-88bb237b200d?w=800', '["https://images.unsplash.com/photo-1519494026892-88bb237b200d?w=800","https://images.unsplash.com/photo-1579154204601-01588f351e67?w=800"]', 1, 'DZD', 10, '1-2 semaines', '["Double canal indépendant","Alarmes multiples","Interface tactile","Historique des perfusions","Batterie de secours 4h"]', '{"Débit":"0.1-1200 mL/h","Précision":"±2%","Seringues":"10-60 mL","Alarmes":"Occlusion, fin, batterie","Batterie":"4h autonomie","Poids":"3.5 kg"}', '[{"name":"Configuration","choices":["Simple canal","Double canal","Triple canal"]}]', '#', 'prd-10', 1, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (11, 'fr', 'aspirateur-de-secretions-portable', 'Aspirateur de Secrétions Portable', 'Soins', '350 € HT', 'Aspirateur médical léger avec batterie intégrée', '<p>Aspirateur de secrétions portable avec batterie intégrée pour une utilisation mobile. Idéal pour les soins à domicile, les transports sanitaires et les interventions d''urgence.</p><h3>Mobilité</h3><ul><li>Batterie lithium : 2h d''autonomie</li><li>Poids : seulement 2.5 kg</li><li>Dépression réglable : 0 à -600 mmHg</li><li>Réservoir : 1L autoclavable</li></ul>', 'https://images.unsplash.com/photo-1579154204601-01588f351e67?w=800', '["https://images.unsplash.com/photo-1579154204601-01588f351e67?w=800","https://images.unsplash.com/photo-1583947215259-38e31be8751f?w=800"]', 1, 'DZD', 11, '3-5 jours', '["Batterie intégrée 2h","Ultra-léger 2.5 kg","Dépression réglable","Réservoir autoclavable","Kit de sondes inclus"]', '{"Dépression":"0 à -600 mmHg","Débit":"20 L/min","Réservoir":"1L","Batterie":"Lithium 2h","Poids":"2.5 kg","Niveau sonore":"<60 dB"}', '[{"name":"Pack","choices":["Appareil seul","Pack avec sondes","Pack complet transport"]}]', '#', 'prd-11', 1, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (12, 'fr', 'balance-bebe-numerique', 'Balance Bébé Numérique', 'Pédiatrie', '220 € HT', 'Balance de précision avec fonction tare et maintien', '<p>Balance bébé numérique de haute précision spécialement conçue pour la pesée des nourrissons et des jeunes enfants. Fonction maintien pour les bébés agités.</p><h3>Précision pédiatrique</h3><ul><li>Capacité : 20 kg</li><li>Précision : 5g</li><li>Fonction tare pour soustraire le poids des couches</li><li>Fonction maintien (Hold) pour bébés agités</li></ul>', 'https://images.unsplash.com/photo-1583947215259-38e31be8751f?w=800', '["https://images.unsplash.com/photo-1583947215259-38e31be8751f?w=800","https://images.unsplash.com/photo-1576091160399-112ba8d25d1d?w=800"]', 1, 'DZD', 12, '1 semaine', '["Précision 5g","Fonction maintien","Fonction tare","Plateau antidérapant","Affichage LCD rétroéclairé"]', '{"Capacité":"20 kg","Précision":"5g","Plateau":"55 x 35 cm","Affichage":"LCD rétroéclairé","Alimentation":"Secteur ou piles","Poids":"4 kg"}', '[{"name":"Accessoires","choices":["Balance seule","Avec toise murale","Pack complet pédiatrie"]}]', '#', 'prd-12', 1, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (13, 'fr', 'nebuliseur-a-compression', 'Nébuliseur à Compression', 'Respiratoire', '85 € HT', 'Nébuliseur domestique et professionnel silencieux', '<p>Nébuliseur à compression pour l''administration de traitements respiratoires. Fonctionnement silencieux idéal pour une utilisation à domicile ou en cabinet médical.</p><h3>Performance</h3><ul><li>Taille des particules : 1-5 μm</li><li>Débit : 0.2 mL/min</li><li>Réservoir médicamenteux : 6 mL</li><li>Niveau sonore : <50 dB</li></ul>', 'https://images.unsplash.com/photo-1576091160399-112ba8d25d1d?w=800', '["https://images.unsplash.com/photo-1576091160399-112ba8d25d1d?w=800","https://images.unsplash.com/photo-1584483766114-2cea6fac255f?w=800"]', 1, 'DZD', 13, '24-48h', '["Fonctionnement silencieux","Particules fines 1-5μm","Masques adulte et enfant","Embout buccal inclus","Facile à nettoyer"]', '{"Particules":"1-5 μm","Débit":"0.2 mL/min","Réservoir":"6 mL","Bruit":"<50 dB","Puissance":"130W","Poids":"1.2 kg"}', '[{"name":"Pack","choices":["Nébuliseur seul","Pack avec masques","Pack famille complet"]}]', '#', 'prd-13', 1, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (14, 'fr', 'fauteuil-roulant-leger-aluminium', 'Fauteuil Roulant Léger Aluminium', 'Mobilité', '450 € HT', 'Fauteuil pliable, ultra-léger et ergonomique', '<p>Fauteuil roulant en aluminium ultra-léger avec structure pliable pour un transport facile. Conçu pour une utilisation quotidienne avec confort et sécurité.</p><h3>Légèreté et confort</h3><ul><li>Poids : seulement 12 kg</li><li>Structure en aluminium anodisé</li><li>Assise et dossier rembourrés</li><li>Repose-pieds relevables et amovibles</li></ul>', 'https://images.unsplash.com/photo-1584982751601-97dcc096659c?w=800', '["https://images.unsplash.com/photo-1584982751601-97dcc096659c?w=800","https://images.unsplash.com/photo-1519494026892-88bb237b200d?w=800"]', 1, 'DZD', 14, '1 semaine', '["Ultra-léger 12 kg","Structure pliable","Assise rembourrée","Repose-pieds amovibles","Freins à main"]', '{"Poids":"12 kg","Largeur assise":"40-50 cm","Roues arrière":"24 pouces","Charge max":"120 kg","Pliage":"Compact","Matériau":"Aluminium anodisé"}', '[{"name":"Largeur d''assise","choices":["40 cm","45 cm","50 cm"]},{"name":"Accessoires","choices":["Standard","Avec tablette","Pack complet"]}]', '#', 'prd-14', 1, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (15, 'fr', 'moniteur-de-signes-vitaux-multiparametres', 'Moniteur de Signes Vitaux Multiparamètres', 'Urgence', '2 800 € HT', 'Surveillance ECG, SpO2, NIBP et Température', '<p>Moniteur patient multiparamètres de haute performance pour la surveillance continue des signes vitaux en temps réel. Écran tactile couleur haute résolution.</p><h3>Paramètres surveillés</h3><ul><li>ECG 3/5 dérivations avec analyse des arythmies</li><li>SpO2 (saturation en oxygène)</li><li>NIBP (pression artérielle non invasive)</li><li>Température (2 voies)</li><li>Fréquence respiratoire</li></ul>', 'https://images.unsplash.com/photo-1516549655169-df83a0774514?w=800', '["https://images.unsplash.com/photo-1516549655169-df83a0774514?w=800","https://images.unsplash.com/photo-1579154204601-01588f351e67?w=800","https://images.unsplash.com/photo-1551076805-e1869033e561?w=800"]', 1, 'DZD', 15, '2-3 semaines', '["Écran tactile couleur","ECG 3/5 dérivations","Alarmes configurables","Interface réseau","Batterie 4h","Historique des événements"]', '{"Écran":"12-15 pouces tactile","ECG":"3/5 dérivations","SpO2":"Pléthysmographie","NIBP":"Oscillométrique","Température":"2 voies","Batterie":"4h autonomie"}', '[{"name":"Écran","choices":["12 pouces","15 pouces"]},{"name":"Modules","choices":["Standard (ECG+SpO2+NIBP)","Complet (+Temp+Resp)"]}]', '#', 'prd-15', 1, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (1001, 'en', 'portable-ultrasound-pro-x1', 'Portable Ultrasound Pro X1', 'Diagnostic', 'On Quote', 'High-resolution ultrasound for portable medical imaging', '<p>The Portable Ultrasound Pro X1 represents excellence in mobile medical imaging. Equipped with a 15-inch HD touchscreen and interchangeable multi-frequency probes, this device offers exceptional image quality comparable to fixed ultrasound systems.</p><h3>Main Features</h3><ul><li>15-inch touchscreen with 1920x1080 resolution</li><li>Optimized portability (weight: 3.2 kg)</li><li>6-hour battery life with built-in battery</li><li>Wi-Fi and Bluetooth connectivity for data transfer</li><li>DICOM compatible for PACS integration</li></ul><h3>Clinical Applications</h3><p>Ideal for home consultations, rural interventions, emergency services, and mobile medical practices.</p>', 'https://images.unsplash.com/photo-1579154204601-01588f351e67?w=800', '["https://images.unsplash.com/photo-1579154204601-01588f351e67?w=800","https://images.unsplash.com/photo-1516549655169-df83a0774514?w=800","https://images.unsplash.com/photo-1551076805-e1869033e561?w=800","https://images.unsplash.com/photo-1576091160399-112ba8d25d1d?w=800"]', 1, 'DZD', 1, '2-3 weeks', '["Real-time 4D imaging","Color and pulsed Doppler mode","Advanced automatic measurements","DICOM compatible export","Multilingual interface"]', '{"Screen":"15-inch HD touchscreen","Weight":"3.2 kg","Battery Life":"6 hours","Probes":"4 probes included","Connectivity":"WiFi, Bluetooth, USB-C","Resolution":"Full HD 1920x1080"}', '[{"name":"Configuration","choices":["Standard","Pro (Additional Probes)"]},{"name":"Warranty","choices":["2 years","3 years","5 years"]}]', '#', 'prd-1', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (1002, 'en', 'premium-electric-examination-table', 'Premium Electric Examination Table', 'Equipment', '€2,450 excl. VAT', 'Height-adjustable electric medical table', '<p>The Premium Electric Examination Table offers optimal comfort for your patients and perfect ergonomics for practitioners. Its silent motors allow smooth height and backrest inclination adjustments.</p><h3>Comfort and Safety</h3><ul><li>Antibacterial faux leather upholstery</li><li>Lockable transport wheels</li><li>Built-in anti-pinch system</li><li>Maximum load: 250 kg</li></ul>', 'https://images.unsplash.com/photo-1519494026892-88bb237b200d?w=800', '["https://images.unsplash.com/photo-1519494026892-88bb237b200d?w=800","https://images.unsplash.com/photo-1584982751601-97dcc096659c?w=800","https://images.unsplash.com/photo-1576091160399-112ba8d25d1d?w=800"]', 1, 'DZD', 2, '1-2 weeks', '["Ergonomic wired remote control","Anti-pinch system","Lockable transport wheels","CE medical certification","Position memory adjustment"]', '{"Maximum Load":"250 kg","Height":"45-95 cm","Dimensions":"190 x 70 cm","Motors":"2 silent electric motors","Weight":"85 kg","Certification":"CE Medical"}', '[{"name":"Upholstery","choices":["Blue Faux Leather","Gray Faux Leather","Black Faux Leather"]},{"name":"Accessories","choices":["Standard","With Cervical Cushion","Complete Pack"]}]', '#', 'prd-2', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (1003, 'en', 'class-b-autoclave-sterilizer', 'Class B Autoclave Sterilizer', 'Surgery', '€3,890 excl. VAT', '23L autoclave for medical instrument sterilization', '<p>Class B autoclave compliant with European standards for sterilizing all types of medical instruments, including hollow and porous instruments. Complete automatic cycle with vacuum drying.</p><h3>Cutting-Edge Technology</h3><ul><li>Built-in thermal printer for traceability</li><li>Intuitive LCD touchscreen</li><li>12 predefined programs</li><li>Automatic Bowie-Dick tests</li></ul>', 'https://images.unsplash.com/photo-1583947215259-38e31be8751f?w=800', '["https://images.unsplash.com/photo-1583947215259-38e31be8751f?w=800","https://images.unsplash.com/photo-1576091160399-112ba8d25d1d?w=800"]', 0, 'DZD', 3, '4-6 weeks', '["Vacuum drying cycle","Built-in thermal printer","Automatic Bowie-Dick tests","LCD touchscreen","Complete traceability"]', '{"Capacity":"23 liters","Pressure":"2.3 bars","Temperature":"134°C","Cycle":"15-25 minutes","Dimensions":"45 x 55 x 45 cm","Weight":"65 kg"}', '[{"name":"Capacity","choices":["18L","23L","30L"]},{"name":"Printer","choices":["With printer","Without printer"]}]', '#', 'prd-3', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (1004, 'en', 'digital-pro-blood-pressure-monitor', 'Digital Pro Blood Pressure Monitor', 'Diagnostic', '€189 excl. VAT', 'Professional blood pressure monitor with 120-measurement memory', '<p>High-precision professional digital blood pressure monitor with universal cuff suitable for all arms. 120-measurement memory with timestamp for optimal monitoring.</p><h3>Advanced Features</h3><ul><li>Irregular heartbeat detection</li><li>Cuff positioning indicator</li><li>Bluetooth connectivity for data transfer</li><li>Dedicated mobile application</li></ul>', 'https://images.unsplash.com/photo-1579684385127-1ef15d508118?w=800', '["https://images.unsplash.com/photo-1579684385127-1ef15d508118?w=800","https://images.unsplash.com/photo-1584982751601-97dcc096659c?w=800"]', 1, 'DZD', 4, '3-5 days', '["Arrhythmia detection","Color-coded WHO indicator","Automatic average","Dedicated mobile app","Universal cuff included"]', '{"Accuracy":"±3 mmHg","Memory":"120 measurements","Cuff":"22-42 cm","Power":"4 AA batteries or mains","Connectivity":"Bluetooth 5.0","Weight":"380 g"}', '[{"name":"Cuff","choices":["Standard (22-32cm)","Large (32-42cm)"]}]', '#', 'prd-4', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (1005, 'en', 'led-binocular-microscope', 'LED Binocular Microscope', 'Diagnostic', '€1,290 excl. VAT', 'Binocular microscope with LED lighting 40x-2000x', '<p>Professional binocular microscope with long-lasting LED lighting and achromatic optical system. Magnification from 40x to 2000x with 4 interchangeable objectives.</p><h3>Quality Optics</h3><ul><li>Corrected achromatic optical system</li><li>30° inclined binocular head</li><li>Precise coaxial focusing</li><li>Mechanical stage with safety stops</li></ul>', 'https://images.unsplash.com/photo-1576091160399-112ba8d25d1d?w=800', '["https://images.unsplash.com/photo-1576091160399-112ba8d25d1d?w=800","https://images.unsplash.com/photo-1516549655169-df83a0774514?w=800"]', 1, 'DZD', 5, '1 week', '["50,000h LED lighting","Achromatic optical system","Precise mechanical stage","30° inclined binocular head","Transport case included"]', '{"Magnification":"40x - 2000x","Objectives":"4x, 10x, 40x, 100x","Eyepieces":"WF10x/18mm","Lighting":"LED 3W","Weight":"6.5 kg"}', '[{"name":"Objectives","choices":["4 objectives (4x,10x,40x,100x)","5 objectives (+20x)"]}]', '#', 'prd-5', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (1006, 'en', 'starter-consumables-pack', 'Starter Consumables Pack', 'Consumables', '€299 excl. VAT', 'Starter pack with gloves, masks, and disinfectants', '<p>Complete pack of medical consumables to start or restock your practice. Contains 10 boxes of nitrile gloves, type IIR surgical masks, hydroalcoholic gel, and sterile compresses.</p><h3>Detailed Contents</h3><ul><li>1000 latex-free and powder-free nitrile gloves</li><li>50 three-ply high-filtration surgical masks</li><li>5L hydroalcoholic gel</li><li>500 non-woven sterile compresses</li></ul>', 'https://images.unsplash.com/photo-1584982751601-97dcc096659c?w=800', '["https://images.unsplash.com/photo-1584982751601-97dcc096659c?w=800","https://images.unsplash.com/photo-1584483766114-2cea6fac255f?w=800"]', 1, 'DZD', 6, '24-48h', '["Latex-free and powder-free gloves","Three-ply high-filtration masks","Gel with moisturizing agents","Non-woven compresses","Fast delivery"]', '{"Gloves":"1000 nitrile units","Masks":"50 type IIR","Gel":"5L hydroalcoholic","Compresses":"500 sterile","Validity":"24 months"}', '[{"name":"Glove Size","choices":["S","M","L","XL","Mixed"]}]', '#', 'prd-6', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (1007, 'en', 'semi-automatic-defibrillator', 'Semi-Automatic Defibrillator', 'Emergency', '€1,850 excl. VAT', 'AED with voice guide and rapid rhythm analysis', '<p>Latest generation Semi-Automatic Defibrillator (AED) with clear voice guide and rapid cardiac rhythm analysis. Designed for use by healthcare professionals and trained first responders.</p><h3>Simplicity of Use</h3><ul><li>Step-by-step voice guide in French</li><li>Rhythm analysis in less than 10 seconds</li><li>Single-use pre-gelled electrodes</li><li>Automatic daily self-test</li></ul>', 'https://images.unsplash.com/photo-1516549655169-df83a0774514?w=800', '["https://images.unsplash.com/photo-1516549655169-df83a0774514?w=800","https://images.unsplash.com/photo-1551076805-e1869033e561?w=800"]', 1, 'DZD', 7, '1 week', '["French voice guide","Rapid rhythm analysis","Daily self-test","Pediatric electrodes available","8-year warranty"]', '{"Weight":"2.1 kg","Battery":"Lithium, 4 years","Energy":"150-200J","Analysis":"Less than 10 seconds","Waterproof":"IP55"}', '[{"name":"Pack","choices":["Device only","Complete pack with cabinet","Pack with training included"]}]', '#', 'prd-7', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (1008, 'en', '5l-oxygen-concentrator', '5L Oxygen Concentrator', 'Respiratory', '€890 excl. VAT', 'Silent medical oxygen concentrator 5L/min', '<p>High-quality medical oxygen concentrator delivering up to 5 liters per minute of 93% pure oxygen. Silent operation ideal for home or office use.</p><h3>Performance</h3><ul><li>Adjustable flow from 0.5 to 5 L/min</li><li>Oxygen purity: 93% ±3%</li><li>Noise level: less than 40 dB</li><li>Pressure and purity alarm</li></ul>', 'https://images.unsplash.com/photo-1584483766114-2cea6fac255f?w=800', '["https://images.unsplash.com/photo-1584483766114-2cea6fac255f?w=800","https://images.unsplash.com/photo-1579684385127-1ef15d508118?w=800"]', 1, 'DZD', 8, '3-5 days', '["Silent operation","Safety alarm","Humidifier included","Easy-to-replace filter","Transport wheels"]', '{"Flow":"0.5-5 L/min","Purity":"93% ±3%","Noise":"<40 dB","Power":"350W","Weight":"15 kg"}', '[{"name":"Accessories","choices":["Standard pack","Pack with trolley","Complete pack with mask"]}]', '#', 'prd-8', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (1009, 'en', 'mobile-led-surgical-light', 'Mobile LED Surgical Light', 'Surgery', '€3,200 excl. VAT', 'High-intensity mobile surgical lighting, shadow-free', '<p>High-performance mobile LED surgical light offering intense, shadow-free surgical lighting. Latest generation LED technology with 50,000-hour lifespan.</p><h3>Professional Lighting</h3><ul><li>Light intensity: 100,000 to 150,000 Lux</li><li>Color temperature: 4500K (daylight)</li><li>CRI > 95 (color rendering)</li><li>Multi-LED anti-shadow system</li></ul>', 'https://images.unsplash.com/photo-1551076805-e1869033e561?w=800', '["https://images.unsplash.com/photo-1551076805-e1869033e561?w=800","https://images.unsplash.com/photo-1519494026892-88bb237b200d?w=800"]', 1, 'DZD', 9, '2 weeks', '["50,000h LED technology","Shadow-free lighting","Adjustable color temperature","Sterilizable","Mobile stand with wheels"]', '{"Intensity":"100,000-150,000 Lux","Color Temperature":"4500K","CRI":">95","LED Lifespan":"50,000h","Weight":"12 kg"}', '[{"name":"Power","choices":["100,000 Lux","150,000 Lux"]},{"name":"Installation","choices":["Mobile on stand","Fixed ceiling mount"]}]', '#', 'prd-9', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (1010, 'en', 'double-electric-syringe-driver', 'Double Electric Syringe Driver', 'Intensive Care', '€1,450 excl. VAT', 'Precision infusion with safety alarms', '<p>Double-channel electric syringe driver for precise medication administration in intensive care and resuscitation. Advanced safety system with multiple alarms.</p><h3>Precision and Safety</h3><ul><li>Flow rate: 0.1 to 1200 mL/h</li><li>Accuracy: ±2%</li><li>Alarms: occlusion, end of infusion, low battery</li><li>Compatible with 10 to 60 mL syringes</li></ul>', 'https://images.unsplash.com/photo-1519494026892-88bb237b200d?w=800', '["https://images.unsplash.com/photo-1519494026892-88bb237b200d?w=800","https://images.unsplash.com/photo-1579154204601-01588f351e67?w=800"]', 1, 'DZD', 10, '1-2 weeks', '["Independent double channel","Multiple alarms","Touch interface","Infusion history","4-hour backup battery"]', '{"Flow Rate":"0.1-1200 mL/h","Accuracy":"±2%","Syringes":"10-60 mL","Alarms":"Occlusion, end, battery","Battery":"4h autonomy","Weight":"3.5 kg"}', '[{"name":"Configuration","choices":["Single channel","Double channel","Triple channel"]}]', '#', 'prd-10', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (1011, 'en', 'portable-suction-unit', 'Portable Suction Unit', 'Care', '€350 excl. VAT', 'Lightweight medical suction unit with built-in battery', '<p>Portable suction unit with built-in battery for mobile use. Ideal for home care, medical transport, and emergency interventions.</p><h3>Mobility</h3><ul><li>Lithium battery: 2h autonomy</li><li>Weight: only 2.5 kg</li><li>Adjustable vacuum: 0 to -600 mmHg</li><li>1L autoclavable reservoir</li></ul>', 'https://images.unsplash.com/photo-1579154204601-01588f351e67?w=800', '["https://images.unsplash.com/photo-1579154204601-01588f351e67?w=800","https://images.unsplash.com/photo-1583947215259-38e31be8751f?w=800"]', 1, 'DZD', 11, '3-5 days', '["2h built-in battery","Ultra-light 2.5 kg","Adjustable vacuum","Autoclavable reservoir","Probe kit included"]', '{"Vacuum":"0 to -600 mmHg","Flow":"20 L/min","Reservoir":"1L","Battery":"Lithium 2h","Weight":"2.5 kg","Noise Level":"<60 dB"}', '[{"name":"Pack","choices":["Device only","Pack with probes","Complete transport pack"]}]', '#', 'prd-11', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (1012, 'en', 'digital-baby-scale', 'Digital Baby Scale', 'Pediatrics', '€220 excl. VAT', 'Precision scale with tare and hold function', '<p>High-precision digital baby scale specially designed for weighing infants and young children. Hold function for restless babies.</p><h3>Pediatric Precision</h3><ul><li>Capacity: 20 kg</li><li>Accuracy: 5g</li><li>Tare function to subtract diaper weight</li><li>Hold function for restless babies</li></ul>', 'https://images.unsplash.com/photo-1583947215259-38e31be8751f?w=800', '["https://images.unsplash.com/photo-1583947215259-38e31be8751f?w=800","https://images.unsplash.com/photo-1576091160399-112ba8d25d1d?w=800"]', 1, 'DZD', 12, '1 week', '["5g accuracy","Hold function","Tare function","Non-slip tray","Backlit LCD display"]', '{"Capacity":"20 kg","Accuracy":"5g","Tray":"55 x 35 cm","Display":"Backlit LCD","Power":"Mains or batteries","Weight":"4 kg"}', '[{"name":"Accessories","choices":["Scale only","With wall stadiometer","Complete pediatric pack"]}]', '#', 'prd-12', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (1013, 'en', 'compression-nebulizer', 'Compression Nebulizer', 'Respiratory', '€85 excl. VAT', 'Silent home and professional nebulizer', '<p>Compression nebulizer for respiratory treatment administration. Silent operation ideal for home or medical office use.</p><h3>Performance</h3><ul><li>Particle size: 1-5 μm</li><li>Flow rate: 0.2 mL/min</li><li>Medication reservoir: 6 mL</li><li>Noise level: <50 dB</li></ul>', 'https://images.unsplash.com/photo-1576091160399-112ba8d25d1d?w=800', '["https://images.unsplash.com/photo-1576091160399-112ba8d25d1d?w=800","https://images.unsplash.com/photo-1584483766114-2cea6fac255f?w=800"]', 1, 'DZD', 13, '24-48h', '["Silent operation","Fine particles 1-5μm","Adult and child masks","Mouthpiece included","Easy to clean"]', '{"Particles":"1-5 μm","Flow":"0.2 mL/min","Reservoir":"6 mL","Noise":"<50 dB","Power":"130W","Weight":"1.2 kg"}', '[{"name":"Pack","choices":["Nebulizer only","Pack with masks","Complete family pack"]}]', '#', 'prd-13', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (1014, 'en', 'lightweight-aluminum-wheelchair', 'Lightweight Aluminum Wheelchair', 'Mobility', '€450 excl. VAT', 'Foldable, ultra-light and ergonomic wheelchair', '<p>Ultra-light aluminum wheelchair with foldable frame for easy transport. Designed for daily use with comfort and safety.</p><h3>Lightness and Comfort</h3><ul><li>Weight: only 12 kg</li><li>Anodized aluminum frame</li><li>Padded seat and backrest</li><li>Lift-up and removable footrests</li></ul>', 'https://images.unsplash.com/photo-1584982751601-97dcc096659c?w=800', '["https://images.unsplash.com/photo-1584982751601-97dcc096659c?w=800","https://images.unsplash.com/photo-1519494026892-88bb237b200d?w=800"]', 1, 'DZD', 14, '1 week', '["Ultra-light 12 kg","Foldable frame","Padded seat","Removable footrests","Hand brakes"]', '{"Weight":"12 kg","Seat Width":"40-50 cm","Rear Wheels":"24 inches","Max Load":"120 kg","Folding":"Compact","Material":"Anodized aluminum"}', '[{"name":"Seat Width","choices":["40 cm","45 cm","50 cm"]},{"name":"Accessories","choices":["Standard","With tray","Complete pack"]}]', '#', 'prd-14', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (1015, 'en', 'multiparameter-vital-signs-monitor', 'Multiparameter Vital Signs Monitor', 'Emergency', '€2,800 excl. VAT', 'ECG, SpO2, NIBP and Temperature monitoring', '<p>High-performance multiparameter patient monitor for continuous real-time vital signs monitoring. High-resolution color touchscreen.</p><h3>Monitored Parameters</h3><ul><li>3/5-lead ECG with arrhythmia analysis</li><li>SpO2 (oxygen saturation)</li><li>NIBP (non-invasive blood pressure)</li><li>Temperature (2 channels)</li><li>Respiratory rate</li></ul>', 'https://images.unsplash.com/photo-1516549655169-df83a0774514?w=800', '["https://images.unsplash.com/photo-1516549655169-df83a0774514?w=800","https://images.unsplash.com/photo-1579154204601-01588f351e67?w=800","https://images.unsplash.com/photo-1551076805-e1869033e561?w=800"]', 1, 'DZD', 15, '2-3 weeks', '["Color touchscreen","3/5-lead ECG","Configurable alarms","Network interface","4h battery","Event history"]', '{"Screen":"12-15 inch touchscreen","ECG":"3/5 leads","SpO2":"Plethysmography","NIBP":"Oscillometric","Temperature":"2 channels","Battery":"4h autonomy"}', '[{"name":"Screen","choices":["12 inches","15 inches"]},{"name":"Modules","choices":["Standard (ECG+SpO2+NIBP)","Complete (+Temp+Resp)"]}]', '#', 'prd-15', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (2001, 'ar', 'جهاز-الموجات-فوق-الصوتية-المحمول-pro-x1', 'جهاز الموجات فوق الصوتية المحمول Pro X1', 'التشخيص', 'حسب العرض', 'جهاز موجات فوق صوتية عالي الدقة للتصوير الطبي المحمول', '<p>يمثل جهاز الموجات فوق الصوتية المحمول Pro X1 التميز في التصوير الطبي المتنقل. مجهز بشاشة لمس HD مقاس 15 بوصة ومسبارات متعددة الترددات قابلة للتبديل، يوفر هذا الجهاز جودة صورة استثنائية مماثلة لأجهزة الموجات فوق الصوتية الثابتة.</p><h3>الميزات الرئيسية</h3><ul><li>شاشة لمس 15 بوصة بدقة 1920x1080</li><li>قابلية نقل محسنة (الوزن: 3.2 كجم)</li><li>عمر بطارية 6 ساعات مع بطارية مدمجة</li><li>اتصال Wi-Fi و Bluetooth لنقل البيانات</li><li>متوافق مع DICOM للتكامل مع PACS</li></ul><h3>التطبيقات السريرية</h3><p>مثالي للاستشارات المنزلية، والتدخلات في المناطق الريفية، وخدمات الطوارئ، والممارسات الطبية المتنقلة.</p>', 'https://images.unsplash.com/photo-1579154204601-01588f351e67?w=800', '["https://images.unsplash.com/photo-1579154204601-01588f351e67?w=800","https://images.unsplash.com/photo-1516549655169-df83a0774514?w=800","https://images.unsplash.com/photo-1551076805-e1869033e561?w=800","https://images.unsplash.com/photo-1576091160399-112ba8d25d1d?w=800"]', 1, 'DZD', 1, '2-3 أسابيع', '["تصوير 4D في الوقت الفعلي","وضع دوبلر ملون ونبضي","قياسات تلقائية متقدمة","تصدير متوافق مع DICOM","واجهة متعددة اللغات"]', '{"الشاشة":"15 بوصة لمس HD","الوزن":"3.2 كجم","عمر البطارية":"6 ساعات","المسبارات":"4 مسبارات مضمنة","الاتصال":"WiFi، Bluetooth، USB-C","الدقة":"Full HD 1920x1080"}', '[{"name":"التكوين","choices":["قياسي","احترافي (مسبارات إضافية)"]},{"name":"الضمان","choices":["سنتان","3 سنوات","5 سنوات"]}]', '#', 'prd-1', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (2002, 'ar', 'سرير-فحص-كهربائي-فاخر', 'سرير فحص كهربائي فاخر', 'المعدات', '2,450 € بدون ضريبة', 'سرير طبي كهربائي قابل لتعديل الارتفاع', '<p>يوفر سرير الفحص الكهربائي الفاخر راحة مثالية لمرضاك وبيئة عمل مثالية للممارسين. تسمح محركاته الصامتة بضبط سلس للارتفاع وميل مسند الظهر.</p><h3>الراحة والأمان</h3><ul><li>تنجيد جلد صناعي مضاد للبكتيريا</li><li>عجلات نقل قابلة للقفل</li><li>نظام مدمج مضاد للقرص</li><li>الحمولة القصوى: 250 كجم</li></ul>', 'https://images.unsplash.com/photo-1519494026892-88bb237b200d?w=800', '["https://images.unsplash.com/photo-1519494026892-88bb237b200d?w=800","https://images.unsplash.com/photo-1584982751601-97dcc096659c?w=800","https://images.unsplash.com/photo-1576091160399-112ba8d25d1d?w=800"]', 1, 'DZD', 2, '1-2 أسبوع', '["جهاز تحكم سلكي مريح","نظام مضاد للقرص","عجلات نقل قابلة للقفل","شهادة CE الطبية","ضبط ذاكرة الموضع"]', '{"الحمولة القصوى":"250 كجم","الارتفاع":"45-95 سم","الأبعاد":"190 x 70 سم","المحركات":"محركان كهربائيان صامتان","الوزن":"85 كجم","الشهادة":"CE طبي"}', '[{"name":"التنجيد","choices":["جلد صناعي أزرق","جلد صناعي رمادي","جلد صناعي أسود"]},{"name":"الإكسسوارات","choices":["قياسي","مع وسادة عنق","حزمة كاملة"]}]', '#', 'prd-2', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (2003, 'ar', 'معقم-ا-وتوكلاف-الفي-ة-b', 'معقم أوتوكلاف الفئة B', 'الجراحة', '3,890 € بدون ضريبة', 'أوتوكلاف 23 لتر لتعقيم الأدوات الطبية', '<p>أوتوكلاف من الفئة B متوافق مع المعايير الأوروبية لتعقيم جميع أنواع الأدوات الطبية، بما في ذلك الأدوات المجوفة والمسامية. دورة تلقائية كاملة مع تجفيف بالفراغ.</p><h3>تكنولوجيا متطورة</h3><ul><li>طابعة حرارية مدمجة للتتبع</li><li>شاشة LCD لمس بديهية</li><li>12 برنامجًا محددًا مسبقًا</li><li>اختبارات Bowie-Dick تلقائية</li></ul>', 'https://images.unsplash.com/photo-1583947215259-38e31be8751f?w=800', '["https://images.unsplash.com/photo-1583947215259-38e31be8751f?w=800","https://images.unsplash.com/photo-1576091160399-112ba8d25d1d?w=800"]', 0, 'DZD', 3, '4-6 أسابيع', '["دورة تجفيف بالفراغ","طابعة حرارية مدمجة","اختبارات Bowie-Dick تلقائية","شاشة LCD لمس","تتبع كامل"]', '{"السعة":"23 لتر","الضغط":"2.3 بار","درجة الحرارة":"134°C","الدورة":"15-25 دقيقة","الأبعاد":"45 x 55 x 45 سم","الوزن":"65 كجم"}', '[{"name":"السعة","choices":["18 لتر","23 لتر","30 لتر"]},{"name":"الطابعة","choices":["مع طابعة","بدون طابعة"]}]', '#', 'prd-3', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (2004, 'ar', 'جهاز-قياس-ضغط-الدم-الرقمي-الاحترافي', 'جهاز قياس ضغط الدم الرقمي الاحترافي', 'التشخيص', '189 € بدون ضريبة', 'جهاز قياس ضغط احترافي مع ذاكرة 120 قياس', '<p>جهاز قياس ضغط الدم الرقمي الاحترافي عالي الدقة مع كفة عالمية مناسبة لجميع الأذرع. ذاكرة 120 قياس مع ختم زمني للمراقبة المثلى.</p><h3>ميزات متقدمة</h3><ul><li>كشف عدم انتظام ضربات القلب</li><li>مؤشر وضعية الكفة</li><li>اتصال Bluetooth لنقل البيانات</li><li>تطبيق موبايل مخصص</li></ul>', 'https://images.unsplash.com/photo-1579684385127-1ef15d508118?w=800', '["https://images.unsplash.com/photo-1579684385127-1ef15d508118?w=800","https://images.unsplash.com/photo-1584982751601-97dcc096659c?w=800"]', 1, 'DZD', 4, '3-5 أيام', '["كشف عدم انتظام ضربات القلب","مؤشر منظمة الصحة العالمية الملون","متوسط تلقائي","تطبيق موبايل مخصص","كفة عالمية مضمنة"]', '{"الدقة":"±3 ملم زئبق","الذاكرة":"120 قياس","الكفة":"22-42 سم","الطاقة":"4 بطاريات AA أو تيار","الاتصال":"Bluetooth 5.0","الوزن":"380 غ"}', '[{"name":"الكفة","choices":["قياسية (22-32 سم)","كبيرة (32-42 سم)"]}]', '#', 'prd-4', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (2005, 'ar', 'مجهر-ثناي-ي-العيون-led', 'مجهر ثنائي العيون LED', 'التشخيص', '1,290 € بدون ضريبة', 'مجهر ثنائي العيون مع إضاءة LED تكبير 40x-2000x', '<p>مجهر ثنائي العيون احترافي مع إضاءة LED طويلة العمر ونظام بصري لوني. تكبير من 40x إلى 2000x مع 4 عدسات موضوعية قابلة للتبديل.</p><h3>بصريات عالية الجودة</h3><ul><li>نظام بصري لوني مصحح</li><li>رأس ثنائي العيون مائل 30°</li><li>ضبط محوري دقيق</li><li>منصة ميكانيكية مع نقاط أمان</li></ul>', 'https://images.unsplash.com/photo-1576091160399-112ba8d25d1d?w=800', '["https://images.unsplash.com/photo-1576091160399-112ba8d25d1d?w=800","https://images.unsplash.com/photo-1516549655169-df83a0774514?w=800"]', 1, 'DZD', 5, 'أسبوع', '["إضاءة LED 50,000 ساعة","نظام بصري لوني","منصة ميكانيكية دقيقة","رأس ثنائي العيون مائل 30°","حقيبة نقل مضمنة"]', '{"التكبير":"40x - 2000x","العدسات":"4x, 10x, 40x, 100x","العينيات":"WF10x/18mm","الإضاءة":"LED 3W","الوزن":"6.5 كجم"}', '[{"name":"العدسات","choices":["4 عدسات (4x,10x,40x,100x)","5 عدسات (+20x)"]}]', '#', 'prd-5', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (2006, 'ar', 'حزمة-المستهلكات-الابتدائية', 'حزمة المستهلكات الابتدائية', 'المستهلكات', '299 € بدون ضريبة', 'حزمة بدء مع قفازات، كمامات ومعقمات', '<p>حزمة كاملة من المستهلكات الطبية لبدء أو إعادة تزويد عيادتك. تحتوي على 10 علب من قفازات النتريل، كمامات جراحية من النوع IIR، جل كحولي وضغوط معقمة.</p><h3>المحتوى التفصيلي</h3><ul><li>1000 قفاز نتريل خالٍ من اللاتكس والمسحوق</li><li>50 كمامة جراحية ثلاثية الطبقات عالية الترشيح</li><li>5 لتر جل كحولي</li><li>500 ضغطة معقمة غير منسوجة</li></ul>', 'https://images.unsplash.com/photo-1584982751601-97dcc096659c?w=800', '["https://images.unsplash.com/photo-1584982751601-97dcc096659c?w=800","https://images.unsplash.com/photo-1584483766114-2cea6fac255f?w=800"]', 1, 'DZD', 6, '24-48 ساعة', '["قفازات خالية من اللاتكس والمسحوق","كمامات ثلاثية الطبقات عالية الترشيح","جل مع عوامل مرطبة","ضغطات غير منسوجة","توصيل سريع"]', '{"القفازات":"1000 وحدة نتريل","الكمامات":"50 نوع IIR","الجل":"5 لتر كحولي","الضغطات":"500 معقمة","الصلاحية":"24 شهر"}', '[{"name":"مقاس القفازات","choices":["S","M","L","XL","مختلط"]}]', '#', 'prd-6', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (2007, 'ar', 'جهاز-إزالة-الرجفان-شبه-التلقائي', 'جهاز إزالة الرجفان شبه التلقائي', 'الطوارئ', '1,850 € بدون ضريبة', 'جهاز إزالة الرجفان مع دليل صوتي وتحليل سريع للإيقاع', '<p>جهاز إزالة الرجفان شبه التلقائي من الجيل الأخير مع دليل صوتي واضح وتحليل سريع للإيقاع القلبي. مصمم للاستخدام من قبل المهنيين الصحيين والمساعدين المدربين.</p><h3>سهولة الاستخدام</h3><ul><li>دليل صوتي خطوة بخطوة بالعربية</li><li>تحليل الإيقاع في أقل من 10 ثوانٍ</li><li>أقطاب كهربائية مجهزة مسبقًا للاستخدام مرة واحدة</li><li>اختبار ذاتي يومي تلقائي</li></ul>', 'https://images.unsplash.com/photo-1516549655169-df83a0774514?w=800', '["https://images.unsplash.com/photo-1516549655169-df83a0774514?w=800","https://images.unsplash.com/photo-1551076805-e1869033e561?w=800"]', 1, 'DZD', 7, 'أسبوع', '["دليل صوتي بالعربية","تحليل سريع للإيقاع","اختبار ذاتي يومي","أقطاب كهربائية للأطفال متوفرة","ضمان 8 سنوات"]', '{"الوزن":"2.1 كجم","البطارية":"ليثيوم، 4 سنوات","الطاقة":"150-200J","التحليل":"أقل من 10 ثوانٍ","مقاومة الماء":"IP55"}', '[{"name":"الحزمة","choices":["الجهاز فقط","حزمة كاملة مع خزانة","حزمة مع تدريب مضمن"]}]', '#', 'prd-7', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (2008, 'ar', 'جهاز-تركيز-الأكسجين-5-لتر', 'جهاز تركيز الأكسجين 5 لتر', 'الجهاز التنفسي', '890 € بدون ضريبة', 'جهاز تركيز أكسجين طبي صامت 5 لتر/دقيقة', '<p>جهاز تركيز أكسجين طبي عالي الجودة يوفر حتى 5 لترات في الدقيقة من الأكسجين بنقاء 93%. تشغيل صامت مثالي للاستخدام المنزلي أو في العيادة.</p><h3>الأداء</h3><ul><li>تدفق قابل للتعديل من 0.5 إلى 5 لتر/دقيقة</li><li>نقاء الأكسجين: 93% ±3%</li><li>مستوى الضوضاء: أقل من 40 ديسيبل</li><li>إنذار الضغط والنقاء</li></ul>', 'https://images.unsplash.com/photo-1584483766114-2cea6fac255f?w=800', '["https://images.unsplash.com/photo-1584483766114-2cea6fac255f?w=800","https://images.unsplash.com/photo-1579684385127-1ef15d508118?w=800"]', 1, 'DZD', 8, '3-5 أيام', '["تشغيل صامت","إنذار أمان","مرطب مضمن","فلتر سهل الاستبدال","عجلات نقل"]', '{"التدفق":"0.5-5 لتر/دقيقة","النقاء":"93% ±3%","الضوضاء":"<40 ديسيبل","الطاقة":"350W","الوزن":"15 كجم"}', '[{"name":"الإكسسوارات","choices":["حزمة قياسية","حزمة مع عربة","حزمة كاملة مع قناع"]}]', '#', 'prd-8', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (2009, 'ar', 'مصباح-جراحي-led-متنقل', 'مصباح جراحي LED متنقل', 'الجراحة', '3,200 € بدون ضريبة', 'إضاءة جراحية متنقلة عالية الكثافة بدون ظلال', '<p>مصباح جراحي LED متنقل عالي الأداء يوفر إضاءة جراحية مكثفة وبدون ظلال. تكنولوجيا LED من الجيل الأخير مع عمر افتراضي 50,000 ساعة.</p><h3>إضاءة احترافية</h3><ul><li>شدة الإضاءة: 100,000 إلى 150,000 لوكس</li><li>درجة حرارة اللون: 4500K (ضوء النهار)</li><li>مؤشر تجسيد اللون > 95</li><li>نظام متعدد LED مضاد للظلال</li></ul>', 'https://images.unsplash.com/photo-1551076805-e1869033e561?w=800', '["https://images.unsplash.com/photo-1551076805-e1869033e561?w=800","https://images.unsplash.com/photo-1519494026892-88bb237b200d?w=800"]', 1, 'DZD', 9, 'أسبوعان', '["تكنولوجيا LED 50,000 ساعة","إضاءة بدون ظلال","درجة حرارة لون قابلة للتعديل","قابل للتعقيم","قاعدة متنقلة بعجلات"]', '{"الشدة":"100,000-150,000 لوكس","درجة حرارة اللون":"4500K","مؤشر تجسيد اللون":">95","عمر LED":"50,000 ساعة","الوزن":"12 كجم"}', '[{"name":"الطاقة","choices":["100,000 لوكس","150,000 لوكس"]},{"name":"التركيب","choices":["متنقل على قاعدة","سقفي ثابت"]}]', '#', 'prd-9', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (2010, 'ar', 'محقن-كهربائي-مزدوج', 'محقن كهربائي مزدوج', 'العناية المركزة', '1,450 € بدون ضريبة', 'تسريب دقيق مع إنذارات أمان', '<p>محقن كهربائي مزدوج القناة للإدارة الدقيقة للأدوية في العناية المركزة والإنعاش. نظام أمان متقدم مع إنذارات متعددة.</p><h3>الدقة والأمان</h3><ul><li>معدل التدفق: 0.1 إلى 1200 مل/ساعة</li><li>الدقة: ±2%</li><li>إنذارات: انسداد، نهاية التسريب، بطارية ضعيفة</li><li>متوافق مع محاقن 10 إلى 60 مل</li></ul>', 'https://images.unsplash.com/photo-1519494026892-88bb237b200d?w=800', '["https://images.unsplash.com/photo-1519494026892-88bb237b200d?w=800","https://images.unsplash.com/photo-1579154204601-01588f351e67?w=800"]', 1, 'DZD', 10, '1-2 أسبوع', '["قناتان مستقلتان","إنذارات متعددة","واجهة لمس","سجل التسريب","بطارية احتياطية 4 ساعات"]', '{"معدل التدفق":"0.1-1200 مل/ساعة","الدقة":"±2%","المحاقن":"10-60 مل","الإنذارات":"انسداد، نهاية، بطارية","البطارية":"4 ساعات","الوزن":"3.5 كجم"}', '[{"name":"التكوين","choices":["قناة واحدة","قناتان","ثلاث قنوات"]}]', '#', 'prd-10', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (2011, 'ar', 'جهاز-شفط-الإفرازات-المحمول', 'جهاز شفط الإفرازات المحمول', 'الرعاية', '350 € بدون ضريبة', 'جهاز شفط طبي خفيف مع بطارية مدمجة', '<p>جهاز شفط إفرازات محمول مع بطارية مدمجة للاستخدام المتنقل. مثالي للرعاية المنزلية، والنقل الطبي، والتدخلات الطارئة.</p><h3>التنقل</h3><ul><li>بطارية ليثيوم: ساعتان</li><li>الوزن: 2.5 كجم فقط</li><li>ضغط قابل للتعديل: 0 إلى -600 ملم زئبق</li><li>خزان 1 لتر قابل للتعقيم بالحرارة</li></ul>', 'https://images.unsplash.com/photo-1579154204601-01588f351e67?w=800', '["https://images.unsplash.com/photo-1579154204601-01588f351e67?w=800","https://images.unsplash.com/photo-1583947215259-38e31be8751f?w=800"]', 1, 'DZD', 11, '3-5 أيام', '["بطارية مدمجة ساعتان","خفيف جدًا 2.5 كجم","ضغط قابل للتعديل","خزان قابل للتعقيم","مجموعة مجسات مضمنة"]', '{"الضغط":"0 إلى -600 ملم زئبق","التدفق":"20 لتر/دقيقة","الخزان":"1 لتر","البطارية":"ليثيوم ساعتان","الوزن":"2.5 كجم","مستوى الضوضاء":"<60 ديسيبل"}', '[{"name":"الحزمة","choices":["الجهاز فقط","حزمة مع مجسات","حزمة نقل كاملة"]}]', '#', 'prd-11', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (2012, 'ar', 'ميزان-أطفال-رقمي', 'ميزان أطفال رقمي', 'طب الأطفال', '220 € بدون ضريبة', 'ميزان دقيق مع وظيفة الطرح والثبات', '<p>ميزان أطفال رقمي عالي الدقة مصمم خصيصًا لوزن الرضع والأطفال الصغار. وظيفة الثبات للأطفال غير الهادئين.</p><h3>دقة طب الأطفال</h3><ul><li>السعة: 20 كجم</li><li>الدقة: 5 غرام</li><li>وظيفة الطرح لطرح وزن الحفاضات</li><li>وظيفة الثبات للأطفال غير الهادئين</li></ul>', 'https://images.unsplash.com/photo-1583947215259-38e31be8751f?w=800', '["https://images.unsplash.com/photo-1583947215259-38e31be8751f?w=800","https://images.unsplash.com/photo-1576091160399-112ba8d25d1d?w=800"]', 1, 'DZD', 12, 'أسبوع', '["دقة 5 غرام","وظيفة الثبات","وظيفة الطرح","صينية مضادة للانزلاق","شاشة LCD مضاءة"]', '{"السعة":"20 كجم","الدقة":"5 غرام","الصينية":"55 x 35 سم","الشاشة":"LCD مضاءة","الطاقة":"تيار أو بطاريات","الوزن":"4 كجم"}', '[{"name":"الإكسسوارات","choices":["الميزان فقط","مع مقياس الطول الجداري","حزمة طب أطفال كاملة"]}]', '#', 'prd-12', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (2013, 'ar', 'جهاز-رذاذ-بالضغط', 'جهاز رذاذ بالضغط', 'الجهاز التنفسي', '85 € بدون ضريبة', 'جهاز رذاذ منزلي واحترافي صامت', '<p>جهاز رذاذ بالضغط لإدارة العلاجات التنفسية. تشغيل صامت مثالي للاستخدام المنزلي أو في العيادة الطبية.</p><h3>الأداء</h3><ul><li>حجم الجسيمات: 1-5 ميكرومتر</li><li>معدل التدفق: 0.2 مل/دقيقة</li><li>خزان الدواء: 6 مل</li><li>مستوى الضوضاء: <50 ديسيبل</li></ul>', 'https://images.unsplash.com/photo-1576091160399-112ba8d25d1d?w=800', '["https://images.unsplash.com/photo-1576091160399-112ba8d25d1d?w=800","https://images.unsplash.com/photo-1584483766114-2cea6fac255f?w=800"]', 1, 'DZD', 13, '24-48 ساعة', '["تشغيل صامت","جسيمات دقيقة 1-5 ميكرومتر","أقنعة للبالغين والأطفال","قطعة فم مضمنة","سهل التنظيف"]', '{"الجسيمات":"1-5 ميكرومتر","التدفق":"0.2 مل/دقيقة","الخزان":"6 مل","الضوضاء":"<50 ديسيبل","الطاقة":"130W","الوزن":"1.2 كجم"}', '[{"name":"الحزمة","choices":["جهاز الرذاذ فقط","حزمة مع أقنعة","حزمة عائلية كاملة"]}]', '#', 'prd-13', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (2014, 'ar', 'كرسي-متحرك-خفيف-من-الألمنيوم', 'كرسي متحرك خفيف من الألمنيوم', 'التنقل', '450 € بدون ضريبة', 'كرسي متحرك قابل للطي، خفيف جدًا ومريح', '<p>كرسي متحرك من الألمنيوم خفيف جدًا بهيكل قابل للطي للنقل السهل. مصمم للاستخدام اليومي مع الراحة والأمان.</p><h3>الخفة والراحة</h3><ul><li>الوزن: 12 كجم فقط</li><li>هيكل من الألمنيوم المؤكسد</li><li>مقعد ومسند ظهر مبطنان</li><li>مساند قدم قابلة للرفع والإزالة</li></ul>', 'https://images.unsplash.com/photo-1584982751601-97dcc096659c?w=800', '["https://images.unsplash.com/photo-1584982751601-97dcc096659c?w=800","https://images.unsplash.com/photo-1519494026892-88bb237b200d?w=800"]', 1, 'DZD', 14, 'أسبوع', '["خفيف جدًا 12 كجم","هيكل قابل للطي","مقعد مبطن","مساند قدم قابلة للإزالة","فرامل يدوية"]', '{"الوزن":"12 كجم","عرض المقعد":"40-50 سم","العجلات الخلفية":"24 بوصة","الحمولة القصوى":"120 كجم","الطي":"مضغوط","المادة":"ألمنيوم مؤكسد"}', '[{"name":"عرض المقعد","choices":["40 سم","45 سم","50 سم"]},{"name":"الإكسسوارات","choices":["قياسي","مع صينية","حزمة كاملة"]}]', '#', 'prd-14', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (2015, 'ar', 'جهاز-مراقبة-العلامات-الحيوية-متعدد-المعايير', 'جهاز مراقبة العلامات الحيوية متعدد المعايير', 'الطوارئ', '2,800 € بدون ضريبة', 'مراقبة تخطيط القلب، SpO2، ضغط الدم ودرجة الحرارة', '<p>جهاز مراقبة المريض متعدد المعايير عالي الأداء للمراقبة المستمرة للعلامات الحيوية في الوقت الفعلي. شاشة لمس ملونة عالية الدقة.</p><h3>المعايير المراقبة</h3><ul><li>تخطيط القلب 3/5 مشتقات مع تحليل عدم انتظام ضربات القلب</li><li>SpO2 (تشبع الأكسجين)</li><li>ضغط الدم غير الباضع (NIBP)</li><li>درجة الحرارة (قناتان)</li><li>معدل التنفس</li></ul>', 'https://images.unsplash.com/photo-1516549655169-df83a0774514?w=800', '["https://images.unsplash.com/photo-1516549655169-df83a0774514?w=800","https://images.unsplash.com/photo-1579154204601-01588f351e67?w=800","https://images.unsplash.com/photo-1551076805-e1869033e561?w=800"]', 1, 'DZD', 15, '2-3 أسابيع', '["شاشة لمس ملونة","تخطيط القلب 3/5 مشتقات","إنذارات قابلة للتكوين","واجهة شبكة","بطارية 4 ساعات","سجل الأحداث"]', '{"الشاشة":"12-15 بوصة لمس","تخطيط القلب":"3/5 مشتقات","SpO2":"مخطط حجم الدم","ضغط الدم":"تذبذبي","درجة الحرارة":"قناتان","البطارية":"4 ساعات"}', '[{"name":"الشاشة","choices":["12 بوصة","15 بوصة"]},{"name":"الوحدات","choices":["قياسية (ECG+SpO2+NIBP)","كاملة (+حرارة+تنفس)"]}]', '#', 'prd-15', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3))
INSERT INTO `authors` (`id`, `locale`, `slug`, `name`, `role`, `bio`, `isFallback`, `sortOrder`, `legacyId`, `isDefault`, `status`, `createdAt`, `updatedAt`)
VALUES
  (1, 'fr', 'dr-marie-laurent', 'Dr. Marie Laurent', 'Directrice médicale', 'Spécialiste de l''imagerie médicale, elle accompagne les établissements de santé dans le choix et la mise en service de leurs équipements de diagnostic.', 0, 1, 'author-1', 1, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (2, 'fr', 'jean-dupont', 'Jean Dupont', 'Directeur des partenariats', 'Il pilote les alliances industrielles de SARI Système et le développement du réseau de distribution en Algérie.', 0, 2, 'author-2', 1, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (3, 'fr', 'service-formation', 'Service Formation', 'Équipe pédagogique', 'L''équipe conçoit et anime les programmes de formation destinés aux praticiens et aux techniciens biomédicaux.', 0, 3, 'author-3', 1, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (4, 'fr', 'direction-qualite', 'Direction Qualité', 'Direction qualité et conformité', 'Elle veille au respect des normes ISO et à la conformité réglementaire de l''ensemble du catalogue.', 0, 4, 'author-4', 1, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (5, 'fr', 'dr-philippe-martin', 'Dr. Philippe Martin', 'Consultant en hygiène et stérilisation', 'Il conseille les cabinets et cliniques sur les protocoles de stérilisation et la prévention du risque infectieux.', 0, 5, 'author-5', 1, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (6, 'fr', 'service-technique', 'Service Technique', 'Bureau d''études techniques', 'Le bureau d''études évalue les performances des équipements et rédige les notices d''installation.', 0, 6, 'author-6', 1, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (7, 'fr', 'equipe-sari', 'Équipe SARI', 'Rédaction SARI Système', 'La rédaction de SARI Système publie les actualités de l''entreprise, les retours d''événements et les annonces produits.', 1, 7, 'author-7', 1, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (8, 'fr', 'service-juridique', 'Service Juridique', 'Affaires réglementaires', 'Le service suit l''évolution de la réglementation applicable aux dispositifs médicaux et en explique les incidences.', 0, 8, 'author-8', 1, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (9, 'fr', 'service-sav', 'Service SAV', 'Service après-vente et maintenance', 'L''équipe assure la maintenance préventive et curative du parc installé chez nos clients.', 0, 9, 'author-9', 1, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (10, 'fr', 'equipe-rse', 'Équipe RSE', 'Responsabilité sociétale', 'L''équipe conduit les engagements environnementaux de l''entreprise et l''éco-conception des gammes.', 0, 10, 'author-10', 1, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (11, 'fr', 'dr-thomas-bernard', 'Dr. Thomas Bernard', 'Spécialiste en télémédecine', 'Il étudie les usages de la télémédecine et anime les webinaires consacrés aux pratiques à distance.', 0, 11, 'author-11', 1, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (12, 'fr', 'service-rh', 'Service RH', 'Ressources humaines', 'Le service publie les offres d''emploi et accompagne les candidats tout au long du recrutement.', 0, 12, 'author-12', 1, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (13, 'fr', 'service-commercial', 'Service Commercial', 'Ingénierie commerciale', 'L''équipe conçoit les solutions d''équipement complètes et documente les projets réalisés.', 0, 13, 'author-13', 1, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (14, 'fr', 'direction-innovation', 'Direction Innovation', 'Direction innovation et veille technologique', 'Elle analyse les tendances du marché médical et prépare les gammes de demain.', 0, 14, 'author-14', 1, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (1001, 'en', 'dr-marie-laurent', 'Dr. Marie Laurent', 'Medical Director', 'A medical imaging specialist, she supports healthcare facilities in selecting and commissioning their diagnostic equipment.', 0, 1, 'author-1', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (1002, 'en', 'jean-dupont', 'Jean Dupont', 'Head of Partnerships', 'He leads SARI Système''s industrial alliances and the growth of its distribution network in Algeria.', 0, 2, 'author-2', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (1003, 'en', 'service-formation', 'Service Formation', 'Training Team', 'The team designs and delivers training programmes for practitioners and biomedical technicians.', 0, 3, 'author-3', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (1004, 'en', 'direction-qualite', 'Direction Qualité', 'Quality & Compliance Department', 'It ensures ISO compliance and regulatory conformity across the entire catalogue.', 0, 4, 'author-4', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (1005, 'en', 'dr-philippe-martin', 'Dr. Philippe Martin', 'Hygiene & Sterilisation Consultant', 'He advises practices and clinics on sterilisation protocols and infection risk prevention.', 0, 5, 'author-5', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (1006, 'en', 'service-technique', 'Service Technique', 'Technical Engineering Office', 'The engineering office assesses equipment performance and writes the installation guides.', 0, 6, 'author-6', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (1007, 'en', 'equipe-sari', 'Équipe SARI', 'SARI Système Editorial Team', 'SARI Système''s editorial team publishes company news, event reports and product announcements.', 1, 7, 'author-7', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (1008, 'en', 'service-juridique', 'Service Juridique', 'Regulatory Affairs', 'The department tracks medical device regulations and explains their practical impact.', 0, 8, 'author-8', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (1009, 'en', 'service-sav', 'Service SAV', 'After-Sales & Maintenance', 'The team handles preventive and corrective maintenance of the equipment installed at our customers'' sites.', 0, 9, 'author-9', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (1010, 'en', 'equipe-rse', 'Équipe RSE', 'Corporate Social Responsibility', 'The team drives the company''s environmental commitments and the eco-design of its ranges.', 0, 10, 'author-10', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (1011, 'en', 'dr-thomas-bernard', 'Dr. Thomas Bernard', 'Telemedicine Specialist', 'He studies telemedicine use cases and hosts the webinars devoted to remote practice.', 0, 11, 'author-11', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (1012, 'en', 'service-rh', 'Service RH', 'Human Resources', 'The department publishes job openings and supports candidates throughout the hiring process.', 0, 12, 'author-12', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (1013, 'en', 'service-commercial', 'Service Commercial', 'Sales Engineering', 'The team designs complete equipment solutions and documents the projects delivered.', 0, 13, 'author-13', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (1014, 'en', 'direction-innovation', 'Direction Innovation', 'Innovation & Technology Watch', 'It analyses medical market trends and prepares tomorrow''s product ranges.', 0, 14, 'author-14', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (2001, 'ar', 'dr-marie-laurent', 'د. ماري لوران', 'المديرة الطبية', 'متخصصة في التصوير الطبي، ترافق المؤسسات الصحية في اختيار معدات التشخيص وتشغيلها.', 0, 1, 'author-1', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (2002, 'ar', 'jean-dupont', 'جون دوبون', 'مدير الشراكات', 'يقود التحالفات الصناعية لساري سيستم وتطوير شبكة التوزيع في الجزائر.', 0, 2, 'author-2', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (2003, 'ar', 'service-formation', 'قسم التدريب', 'الفريق التربوي', 'يصمم الفريق برامج التدريب للممارسين والتقنيين الطبيين وينفذها.', 0, 3, 'author-3', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (2004, 'ar', 'direction-qualite', 'إدارة الجودة', 'إدارة الجودة والمطابقة', 'تسهر على احترام معايير الأيزو والمطابقة التنظيمية لكامل الكتالوج.', 0, 4, 'author-4', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (2005, 'ar', 'dr-philippe-martin', 'د. فيليب مارتان', 'استشاري النظافة والتعقيم', 'يقدم المشورة للعيادات حول بروتوكولات التعقيم والوقاية من مخاطر العدوى.', 0, 5, 'author-5', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (2006, 'ar', 'service-technique', 'الخدمة التقنية', 'مكتب الدراسات التقنية', 'يقيّم مكتب الدراسات أداء المعدات ويحرر أدلة التركيب.', 0, 6, 'author-6', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (2007, 'ar', 'equipe-sari', 'فريق ساري', 'تحرير ساري سيستم', 'ينشر فريق تحرير ساري سيستم أخبار الشركة وتقارير الفعاليات وإعلانات المنتجات.', 1, 7, 'author-7', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (2008, 'ar', 'service-juridique', 'القسم القانوني', 'الشؤون التنظيمية', 'يتابع القسم تطور التنظيمات الخاصة بالأجهزة الطبية ويشرح آثارها.', 0, 8, 'author-8', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (2009, 'ar', 'service-sav', 'خدمة ما بعد البيع', 'خدمة ما بعد البيع والصيانة', 'يضمن الفريق الصيانة الوقائية والتصحيحية للمعدات المركبة لدى عملائنا.', 0, 9, 'author-9', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (2010, 'ar', 'equipe-rse', 'فريق المسؤولية المجتمعية', 'المسؤولية المجتمعية للشركة', 'يقود الفريق الالتزامات البيئية للشركة والتصميم البيئي لمجموعات المنتجات.', 0, 10, 'author-10', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (2011, 'ar', 'dr-thomas-bernard', 'د. توماس برنار', 'أخصائي الطب عن بعد', 'يدرس استخدامات الطب عن بعد ويقدم الندوات الإلكترونية المخصصة للممارسة عن بعد.', 0, 11, 'author-11', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (2012, 'ar', 'service-rh', 'قسم الموارد البشرية', 'الموارد البشرية', 'ينشر القسم عروض العمل ويرافق المترشحين طوال مسار التوظيف.', 0, 12, 'author-12', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (2013, 'ar', 'service-commercial', 'القسم التجاري', 'الهندسة التجارية', 'يصمم الفريق حلول التجهيز المتكاملة ويوثق المشاريع المنجزة.', 0, 13, 'author-13', 0, 'published', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
