INSERT INTO `news_articles` (`id`, `locale`, `slug`, `title`, `category`, `classification`, `sujet`, `authorName`, `authorId`, `date`, `publicationDate`, `readTime`, `shortDesc`, `fullContent`, `image`, `legacyId`, `isDefault`, `status`, `publishedAt`, `createdAt`, `updatedAt`)
VALUES
  (1, 'fr', 'nouvelle-gamme-echographes-portables-derniere-generation', 'Nouvelle gamme d''échographes portables dernière génération', 'Produits', 'Innovation', 'IA dans l''imagerie', 'Dr. Marie Laurent', 1, '2024-01-15 00:00:00', '2024-01-15 00:00:00', '5 min', 'Découvrez notre nouvelle collection avec IA intégrée', '<p>Contenu détaillé de l''article sur les échographes...</p>', 'https://images.unsplash.com/photo-1579154204601-01588f351e67?w=800', 'news-1', 1, 'published', '2024-01-15 00:00:00', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (2, 'fr', 'partenariat-strategique-avec-un-leader-mondial-de-imagerie', 'Partenariat stratégique avec un leader mondial de l''imagerie', 'Entreprise', 'Partenariat', 'Expansion', 'Jean Dupont', 2, '2024-01-10 00:00:00', '2024-01-10 00:00:00', '4 min', 'SARI Système signe un accord de distribution exclusive', '<p>Contenu détaillé du partenariat...</p>', 'https://images.unsplash.com/photo-1560472354-b33ff0c44a43?w=800', 'news-2', 1, 'published', '2024-01-10 00:00:00', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (3, 'fr', 'formation-continue-2024-calendrier-disponible', 'Formation continue 2024 : calendrier disponible', 'Formation', 'Événement', 'Calendrier', 'Service Formation', 3, '2024-01-05 00:00:00', '2024-01-05 00:00:00', '3 min', 'Découvrez le calendrier complet de nos formations', '<p>Contenu détaillé des formations...</p>', 'https://images.unsplash.com/photo-1524178232363-1fb2b075b655?w=800', 'news-3', 1, 'published', '2024-01-05 00:00:00', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
  (4, 'fr', 'sari-systeme-obtient-la-certification-iso-13485', 'SARI Système obtient la certification ISO 13485', 'Entreprise', 'Qualité', 'Certification', 'Direction Qualité', 4, '2023-12-20 00:00:00', '2023-12-20 00:00:00', '4 min', 'Reconnaissance de notre engagement qualité', '<p>Contenu détaillé de la certification...</p>', 'https://images.unsplash.com/photo-1540575467063-178a50c2df87?w=800', 'news-4', 1, 'published', '2023-12-20 00:00:00', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
